   6 |     <title>Room Packer</title>
   7 |     <style>
   8 |       * { margin: 0; padding: 0; box-sizing: border-box; }
   9 | 
  10 |       body {
  11 |         background: #1a1a2e;
  12 |         display: flex;
  13 |         flex-direction: column;
  14 |         align-items: center;
