  65 |       .cell:not(.selected):not(.preview):hover { background-color: #f6f669; opacity: 0.7; }
  66 |       .cell.selected:not(.preview):hover        { background-color: #a0e0a0; }
  67 | 
  68 |       #overlay {
  69 |         position: absolute;
  70 |         top: 0; left: 0;
  71 |         width: 768px; height: 768px;
  72 |         pointer-events: none; /* children opt back in */
  73 |       }
  74 | 
  75 |       .table-rect {
  76 |         position: absolute;
  77 |         border: 2px solid rgba(0,0,0,0.35);
  78 |         display: flex;
  79 |         align-items: center;
  80 |         justify-content: center;
  81 |         font-size: 10px;
  82 |         font-weight: bold;
  83 |         color: rgba(0,0,0,0.7);
  84 |         border-radius: 2px;
  85 |         overflow: hidden;
  86 |         white-space: nowrap;
  87 |         pointer-events: all;
  88 |         cursor: grab;
  89 |         transition: box-shadow 0.1s;
  90 |       }
  91 |       .table-rect:hover  { box-shadow: 0 0 0 2px #fff8; }
  92 |       .table-rect.table-selected { box-shadow: 0 0 0 3px #fff, 0 0 0 5px rgba(255,255,255,0.4); }
  93 |       .table-rect.moving { cursor: grabbing; opacity: 0.75; z-index: 10; box-shadow: 0 4px 16px rgba(0,0,0,0.5); border-style: dashed; }
  94 | 
  95 |       /* Dotted overlay shown over the active (not-yet-placed) selection */
  96 |       #selection-overlay {
  97 |         position: absolute;
  98 |         border: 2px dashed rgba(0,0,0,0.55);
  99 |         border-radius: 2px;
 100 |         pointer-events: none;
 101 |         z-index: 8;
 102 |         display: none;
 103 |       }
 104 | 
 105 |       /* Couch furniture */
 106 |       .couch-rect {
 107 |         position: absolute;
 108 |         border: 2px solid rgba(0,0,0,0.35);
 109 |         display: flex;
 110 |         align-items: center;
 111 |         justify-content: center;
 112 |         font-size: 10px;
 113 |         font-weight: bold;
 114 |         color: rgba(0,0,0,0.7);
 115 |         border-radius: 2px;
 116 |         overflow: hidden;
 117 |         white-space: nowrap;
 118 |         pointer-events: all;
 119 |         cursor: grab;
 120 |         transition: box-shadow 0.1s;
 121 |       }
 122 |       .couch-rect:hover  { box-shadow: 0 0 0 2px #fff8; }
 123 |       .couch-rect.table-selected { box-shadow: 0 0 0 3px #fff, 0 0 0 5px rgba(255,255,255,0.4); }
 124 |       .couch-rect.moving { cursor: grabbing; opacity: 0.75; z-index: 10; box-shadow: 0 4px 16px rgba(0,0,0,0.5); border-style: dashed; }
 125 | 
 126 |       /* Couch-placement / resize ghost — follows cursor when couch mode is active */
 127 |       #couch-ghost {
 128 |         position: absolute;
 129 |         border: 2px dashed #b86fc4;
 130 |         background: rgba(184,111,196,0.25);
 131 |         border-radius: 3px;
 132 |         pointer-events: none;
 133 |         z-index: 9;
 134 |         display: none;
 135 |       }
 136 |       #couch-ghost.conflict {
 137 |         border-color: rgba(255,80,80,0.9);
 138 |         background: rgba(255,60,60,0.25);
 139 |       }
 140 | 
 141 |       /* Resize handles on left / right edges of a selected couch */
 142 |       .couch-handle {
 143 |         position: absolute;
 144 |         top: 50%;
 145 |         transform: translateY(-50%);
 146 |         width: 8px;
 147 |         height: 16px;
 148 |         background: #b86fc4;
 149 |         border: 1px solid #fff6;
 150 |         border-radius: 3px;
 151 |         cursor: ew-resize;
 152 |         pointer-events: all;
 153 |         z-index: 11;
 154 |         opacity: 0;
 155 |         transition: opacity 0.15s;
 156 |       }
 157 |       .couch-handle.handle-left  { left:  -5px; top: 50%; transform: translateY(-50%); }
 158 |       .couch-handle.handle-right { right: -5px; top: 50%; transform: translateY(-50%); }
 159 |       .couch-handle.handle-top   { top:   -5px; left: 50%; transform: translateX(-50%); width: 16px; height: 8px; cursor: ns-resize; }
 160 |       .couch-handle.handle-bot   { bottom:-5px; left: 50%; transform: translateX(-50%); width: 16px; height: 8px; cursor: ns-resize; }
 161 |       .table-selected .couch-handle { opacity: 1; }
 162 | 
 163 |       /* Chair furniture — 1×1 circle */
 164 |       .chair-rect {
 165 |         position: absolute;
 166 |         border: 2px solid rgba(0,0,0,0.35);
 167 |         border-radius: 50%;
 168 |         display: flex;
 169 |         align-items: center;
 170 |         justify-content: center;
 171 |         font-size: 7px;
 172 |         font-weight: bold;
 173 |         color: rgba(0,0,0,0.6);
 174 |         overflow: hidden;
 175 |         pointer-events: all;
 176 |         cursor: grab;
 177 |         transition: box-shadow 0.1s;
 178 |       }
 179 |       .chair-rect:hover      { box-shadow: 0 0 0 2px #fff8; }
 180 |       .chair-rect.table-selected { box-shadow: 0 0 0 3px #fff, 0 0 0 5px rgba(255,255,255,0.4); }
 181 |       .chair-rect.moving     { cursor: grabbing; opacity: 0.75; z-index: 10; box-shadow: 0 4px 16px rgba(0,0,0,0.5); border-style: dashed; }
 182 | 
 183 |       /* Stack badge — shown on the topmost chair when count > 1 */
 184 |       .chair-stack-badge {
 185 |         position: absolute;
 186 |         inset: 0;
 187 |         display: flex;
 188 |         align-items: center;
 189 |         justify-content: center;
 190 |         font-size: 8px;
 191 |         font-weight: 900;
 192 |         line-height: 1;
 193 |         color: #fff;
 194 |         text-shadow: 0 0 3px rgba(0,0,0,0.8);
 195 |         pointer-events: none;
 196 |       }
 197 |       /* Ring that thickens when stacked to hint depth */
 198 |       .chair-rect.stacked {
 199 |         border-width: 3px;
 200 |         border-color: rgba(0,0,0,0.6);
 201 |         box-shadow: inset 0 0 0 2px rgba(255,255,255,0.25);
 202 |       }
 203 | 
 204 |       /* Chair-placement ghost */
 205 |       #chair-ghost {
 206 |         position: absolute;
 207 |         border: 2px dashed #4ecdc4;
 208 |         background: rgba(78,205,196,0.25);
 209 |         border-radius: 50%;
 210 |         pointer-events: none;
 211 |         z-index: 9;
 212 |         display: none;
 213 |       }
 214 |       #chair-ghost.conflict {
 215 |         border-color: rgba(255,80,80,0.9);
 216 |         background: rgba(255,60,60,0.25);
 217 |       }
 218 | 
 219 |       /* Ghost preview while dragging a table */
 220 |       .table-ghost {
 221 |         position: absolute;
 222 |         border: 2px dashed rgba(255,255,255,0.6);
 223 |         border-radius: 2px;
 224 |         pointer-events: none;
 225 |         z-index: 9;
 226 |         background: rgba(255,255,255,0.12);
 227 |       }
 228 | 
 229 |       /* ── L-shape sofa ──────────────────────────────────────────────────────── */
 230 |       .lsofa-rect {
 231 |         position: absolute;
 232 |         pointer-events: all;
 233 |         cursor: grab;
 234 |         transition: filter 0.1s;
 235 |       }
 236 |       /* The visible L shape is drawn as an SVG background */
 237 |       .lsofa-rect:hover  { filter: brightness(1.15); }
 238 |       .lsofa-rect.table-selected { filter: brightness(1.2) drop-shadow(0 0 4px #fff); }
 239 |       .lsofa-rect.moving { cursor: grabbing; opacity: 0.75; z-index: 10; }
 240 | 
 241 |       /* Resize handles — shown only when selected */
 242 |       .lsofa-handle {
 243 |         position: absolute;
 244 |         width: 8px;
 245 |         height: 16px;
 246 |         background: #b86fc4;
 247 |         border: 1px solid #fff6;
 248 |         border-radius: 3px;
 249 |         pointer-events: all;
 250 |         z-index: 11;
 251 |         opacity: 0;
 252 |         transition: opacity 0.15s;
 253 |       }
 254 |       .table-selected .lsofa-handle { opacity: 1; }
 255 | 
 256 |       /* L-sofa placement ghost */
 257 |       #lsofa-ghost {
 258 |         position: absolute;
 259 |         pointer-events: none;
 260 |         z-index: 9;
 261 |         display: none;
 262 |       }
 263 |     </style>
 264 |   </head>
 265 |   <body>
 266 |     <div id="toolbar">
 267 |       <button id="btn-table" disabled>🪑 Place Table <span class="hint">[T]</span></button>
 268 |       <button id="btn-couch">🛋️ Sofa <span class="hint">[C]</span></button>
 269 |       <button id="btn-lsofa">📐 L-Sofa <span class="hint">[L]</span></button>
 270 |       <button id="btn-chair">🪑 Chair <span class="hint">[H]</span></button>
 271 |       <button id="btn-edit"   disabled>✏️ Edit <span class="hint">[E]</span></button>
 272 |       <button id="btn-delete" disabled>🗑️ Delete <span class="hint">[D]</span></button>
 273 |     </div>
 274 |     <div id="board-wrap">
 275 |       <div id="board"></div>
 276 |       <div id="overlay"></div>
 277 |       <div id="selection-overlay"></div>
 278 |       <div id="couch-ghost"></div>
 279 |       <div id="chair-ghost"></div>
 280 |       <div id="lsofa-ghost"><canvas id="lsofa-ghost-canvas"></canvas></div>
 281 |     </div>
 282 | 
 283 | 
 284 |     <script>
 285 |       const CELL = 12, SIZE = 64;
 286 |       const board     = document.getElementById("board");
 287 |       const overlay   = document.getElementById("overlay");
 288 |       const selOverlay = document.getElementById("selection-overlay");
 289 |       const btnTable  = document.getElementById("btn-table");
 290 |       const btnCouch  = document.getElementById("btn-couch");
 291 |       const btnLsofa  = document.getElementById("btn-lsofa");
 292 |       const btnChair  = document.getElementById("btn-chair");
 293 |       const btnEdit   = document.getElementById("btn-edit");
 294 |       const btnDelete = document.getElementById("btn-delete");
 295 |       const boardWrap = document.getElementById("board-wrap");
 296 |       const couchGhostEl = document.getElementById("couch-ghost");
 297 |       const chairGhostEl = document.getElementById("chair-ghost");
 298 |       const lsofaGhostEl = document.getElementById("lsofa-ghost");
 299 |       const lsofaGhostCanvas = document.getElementById("lsofa-ghost-canvas");
 300 | 
 301 |       const TABLE_COLORS = [
 302 |         "#e07b54","#5b9bd5","#e8a838","#8e6bbf",
 303 |         "#4caf8a","#d95f8a","#6ab04c","#c0392b",
 304 |       ];
 305 | 
 306 |       // ── State ────────────────────────────────────────────────────────────────
 307 |       let tableCount = 0;
 308 |       const tables    = [];   // { id, rMin,cMin,rMax,cMax, color, label, el }
 309 |       const tableGrid = [];   // tableGrid[row][col] = array of piece ids occupying that cell
 310 |       let selectedTable = null;   // table currently clicked/focused
 311 |       let editingTable  = null;   // table lifted into edit mode
 312 | 
 313 |       let couchCount = 0;
 314 |       let couchMode  = false;     // true while couch-placement is active
 315 |       let ghostOrientation = "h"; // "h" or "v" — orientation of the next couch to be placed
 316 | 
 317 |       let chairCount = 0;
 318 |       let chairMode  = false;
 319 | 
 320 |       let lsofaCount = 0;
 321 |       let lsofaMode  = false;
 322 |       // Variants: "se" "sw" "ne" "nw" — which direction the two arms extend from the corner
 323 |       let lsofaVariant = "se";
 324 |       // Ghost arm lengths (editable via handles during placement ghost drag)
 325 |       let lsofaGhostLenA = 3; // horizontal arm (min 2)
 326 |       let lsofaGhostLenB = 3; // vertical arm   (min 2)
 327 | 
 328 |       // ── Build cell grid ──────────────────────────────────────────────────────
 329 |       const cells = [];
 330 |       for (let row = 0; row < SIZE; row++) {
 331 |         cells[row] = []; tableGrid[row] = [];
 332 |         for (let col = 0; col < SIZE; col++) {
 333 |           const cell = document.createElement("div");
 334 |           cell.classList.add("cell");
 335 |           cell.classList.add((row + col) % 2 === 0 ? "light" : "dark");
 336 |           cell.dataset.row = row; cell.dataset.col = col;
 337 |           cells[row][col] = cell; tableGrid[row][col] = [];
 338 |           board.appendChild(cell);
 339 |         }
 340 |       }
 341 | 
 342 |       // ── Selection helpers ────────────────────────────────────────────────────
 343 |       let selection = null;
 344 |       let isSelecting = false, selStartRow = null, selStartCol = null;
 345 | 
 346 |       function clearClass(cls) {
 347 |         board.querySelectorAll("." + cls).forEach(c => c.classList.remove(cls));
 348 |       }
 349 |       function paintRect(r1,c1,r2,c2,cls) {
 350 |         for (let r=r1;r<=r2;r++) for (let c=c1;c<=c2;c++) cells[r][c].classList.add(cls);
 351 |       }
 352 |       function renderSelection() {
 353 |         clearClass("selected");
 354 |         if (selection) {
 355 |           paintRect(selection.rMin,selection.cMin,selection.rMax,selection.cMax,"selected");
 356 |           selOverlay.style.left    = (selection.cMin * CELL) + "px";
 357 |           selOverlay.style.top     = (selection.rMin * CELL) + "px";
 358 |           selOverlay.style.width   = ((selection.cMax - selection.cMin + 1) * CELL) + "px";
 359 |           selOverlay.style.height  = ((selection.rMax - selection.rMin + 1) * CELL) + "px";
 360 |           selOverlay.style.display = "block";
 361 |         } else {
 362 |           selOverlay.style.display = "none";
 363 |         }
 364 |         btnTable.disabled = !selection;
 365 |         btnEdit.disabled  = !selectedTable;
 366 |       }
 367 |       function selPreviewRect(curRow,curCol) {
 368 |         const dr1=Math.min(selStartRow,curRow), dr2=Math.max(selStartRow,curRow);
 369 |         const dc1=Math.min(selStartCol,curCol), dc2=Math.max(selStartCol,curCol);
 370 |         if (!selection) return {rMin:dr1,cMin:dc1,rMax:dr2,cMax:dc2};
 371 |         return {
 372 |           rMin:Math.min(selection.rMin,dr1), cMin:Math.min(selection.cMin,dc1),
 373 |           rMax:Math.max(selection.rMax,dr2), cMax:Math.max(selection.cMax,dc2),
 374 |         };
 375 |       }
 376 |       function applySelPreview(curRow,curCol) {
 377 |         clearClass("preview");
 378 |         clearClass("conflict");
 379 |         const r = selPreviewRect(curRow,curCol);
 380 |         for (let row=r.rMin;row<=r.rMax;row++) {
 381 |           for (let col=r.cMin;col<=r.cMax;col++) {
 382 |             if (tableGrid[row][col].length > 0) {
 383 |               cells[row][col].classList.add("conflict");
 384 |             } else {
 385 |               cells[row][col].classList.add("preview");
 386 |             }
 387 |           }
 388 |         }
 389 |         // Keep dotted selection outline tracking the live preview rect
 390 |         selOverlay.style.left    = (r.cMin * CELL) + "px";
 391 |         selOverlay.style.top     = (r.rMin * CELL) + "px";
 392 |         selOverlay.style.width   = ((r.cMax - r.cMin + 1) * CELL) + "px";
 393 |         selOverlay.style.height  = ((r.rMax - r.rMin + 1) * CELL) + "px";
 394 |         selOverlay.style.display = "block";
 395 |       }
 396 | 
 397 | 
 398 |       // ── Cell colour helpers ──────────────────────────────────────────────────
 399 |       function resetCell(r,c) {
 400 |         const cell = cells[r][c];
 401 |         cell.style.backgroundColor = "";
 402 |         cell.style.opacity = "";
 403 |         cell.classList.remove("selected","preview");
 404 |         cell.classList.add((r+c)%2===0 ? "light" : "dark");
 405 |         tableGrid[r][c] = [];
 406 |       }
 407 |       function stampTable(t) {
 408 |         for (let r=t.rMin;r<=t.rMax;r++) for (let c=t.cMin;c<=t.cMax;c++) {
 409 |           const cell = cells[r][c];
 410 |           cell.classList.remove("selected","light","dark","preview");
 411 |           cell.style.backgroundColor = t.color;
 412 |           cell.style.opacity = "0.85";
 413 |           if (!tableGrid[r][c].includes(t.id)) tableGrid[r][c].push(t.id);
 414 |           if (t.type === "chair") refreshChairBadge(r, c);
 415 |         }
 416 |       }
 417 |       function eraseTable(t) {
 418 |         for (let r=t.rMin;r<=t.rMax;r++) for (let c=t.cMin;c<=t.cMax;c++) {
 419 |           tableGrid[r][c] = tableGrid[r][c].filter(id => id !== t.id);
 420 |           if (tableGrid[r][c].length === 0) {
 421 |             resetCell(r, c);
 422 |           } else {
 423 |             // Repaint with the topmost remaining piece's colour
 424 |             const topId = tableGrid[r][c][tableGrid[r][c].length - 1];
 425 |             const top   = tables.find(p => p.id === topId);
 426 |             if (top) {
 427 |               cells[r][c].style.backgroundColor = top.color;
 428 |               cells[r][c].style.opacity = "0.85";
 429 |             }
 430 |             // If there are chairs left here, refresh their badge
 431 |             const hasChair = tableGrid[r][c].some(id => {
 432 |               const p = tables.find(q => q.id === id);
 433 |               return p && p.type === "chair";
 434 |             });
 435 |             if (hasChair || t.type === "chair") refreshChairBadge(r, c);
 436 |           }
 437 |         }
 438 |       }
 439 |       function positionEl(t) {
 440 |         t.el.style.left   = (t.cMin * CELL) + "px";
 441 |         t.el.style.top    = (t.rMin * CELL) + "px";
 442 |         t.el.style.width  = ((t.cMax - t.cMin + 1) * CELL) + "px";
 443 |         t.el.style.height = ((t.rMax - t.rMin + 1) * CELL) + "px";
 444 |       }
 445 | 
 446 |       // ── Table selection & edit ───────────────────────────────────────────────
 447 |       function updateToolbar() {
 448 |         btnTable.disabled  = !selection;
 449 |         btnEdit.disabled   = !selectedTable;
 450 |         btnDelete.disabled = !selectedTable;
 451 |       }
 452 | 
 453 |       function selectTable(t) {
 454 |         if (selectedTable) selectedTable.el.classList.remove("table-selected");
 455 |         selectedTable = t;
 456 |         if (t) t.el.classList.add("table-selected");
 457 |         updateToolbar();
 458 |       }
 459 | 
 460 |       function editTable(t) {
 461 |         if (!t) return;
 462 |         // Save original bounds in case user cancels
 463 |         t._editBackup = { rMin: t.rMin, cMin: t.cMin, rMax: t.rMax, cMax: t.cMax };
 464 |         editingTable = t;
 465 |         // Lift the table off the board into the active selection
 466 |         eraseTable(t);
 467 |         t.el.style.display = "none";
 468 |         // Load its area as the current selection
 469 |         selection = { rMin: t.rMin, cMin: t.cMin, rMax: t.rMax, cMax: t.cMax };
 470 |         renderSelection();
 471 |         selectTable(null);
 472 |       }
 473 | 
 474 |       function cancelEdit() {
 475 |         if (!editingTable) return;
 476 |         const t = editingTable;
 477 |         // Restore original position
 478 |         t.rMin = t._editBackup.rMin; t.cMin = t._editBackup.cMin;
 479 |         t.rMax = t._editBackup.rMax; t.cMax = t._editBackup.cMax;
 480 |         delete t._editBackup;
 481 |         stampTable(t);
 482 |         positionEl(t);
 483 |         t.el.style.display = "";
 484 |         editingTable = null;
 485 |         // Clear selection
 486 |         selection = null;
 487 |         clearClass("preview"); clearClass("conflict");
 488 |         renderSelection();
 489 |       }
 490 | 
 491 |       function deleteTable(t) {
 492 |         if (!t) return;
 493 |         // Snapshot chair position before erasing (needed for badge refresh after splice)
 494 |         const wasChair = t.type === "chair";
 495 |         const chairR = t.rMin, chairC = t.cMin;
 496 | 
 497 |         // If this table is currently being edited, cancel the edit first
 498 |         if (editingTable === t) {
 499 |           editingTable = null;
 500 |           delete t._editBackup;
 501 |           selection = null;
 502 |           clearClass("preview"); clearClass("conflict");
 503 |         } else {
 504 |           if (t.type === "lsofa") eraseLsofa(t);
 505 |           else eraseTable(t);
 506 |         }
 507 |         // Remove overlay element
 508 |         if (t.el.parentNode) t.el.parentNode.removeChild(t.el);
 509 |         // Remove from tables array
 510 |         const idx = tables.indexOf(t);
 511 |         if (idx !== -1) tables.splice(idx, 1);
 512 |         // If a stacked chair was deleted, refresh the badge now that t is gone from `tables`
 513 |         if (wasChair) refreshChairBadge(chairR, chairC);
 514 |         // Deselect
 515 |         if (selectedTable === t) selectTable(null);
 516 |         renderSelection();
 517 |       }
 518 | 
 519 |       // ── Conflict detection ───────────────────────────────────────────────────
 520 |       // Returns true if the given rect overlaps any piece (optionally ignoring one id).
 521 |       function hasConflict(rMin,cMin,rMax,cMax,ignoreId=null) {
 522 |         for (let r=rMin;r<=rMax;r++) for (let c=cMin;c<=cMax;c++) {
 523 |           for (const tid of tableGrid[r][c]) {
 524 |             if (tid !== ignoreId) return true;
 525 |           }
 526 |         }
 527 |         return false;
 528 |       }
 529 | 
 530 |       // Chair-specific conflict: only blocks on non-chair pieces (chairs can stack).
 531 |       function hasConflictForChair(row, col, ignoreId=null) {
 532 |         for (const tid of tableGrid[row][col]) {
