 914 |       // ── L-shape sofa ─────────────────────────────────────────────────────────
 915 |       // An L-sofa is defined by:
 916 |       //   corner:  (cornerR, cornerC) — the inner corner cell
 917 |       //   lenA:    horizontal arm length (≥ 2)
 918 |       //   lenB:    vertical arm length   (≥ 2)
 919 |       //   variant: "se" | "sw" | "ne" | "nw"
 920 |       //
 921 |       //  "se": H arm → right, V arm → down   (corner = top-left  of bbox)
 922 |       //  "sw": H arm → left,  V arm → down   (corner = top-right)
 923 |       //  "ne": H arm → right, V arm → up     (corner = bottom-left)
 924 |       //  "nw": H arm → left,  V arm → up     (corner = bottom-right)
 925 | 
 926 |       const LSOFA_COLORS = [
 927 |         "#c0703c","#3c8fc0","#7ac03c","#c03c8a",
 928 |         "#3cc09a","#c0b03c","#803cc0","#c05a3c",
 929 |       ];
 930 |       const LSOFA_VARIANT_CYCLE = ["se","sw","nw","ne"];
 931 | 
 932 |       function lsofaBBox(cornerR, cornerC, lenA, lenB, variant) {
 933 |         switch (variant) {
 934 |           case "se": return { rMin: cornerR,            cMin: cornerC,            rMax: cornerR + lenB - 1, cMax: cornerC + lenA - 1 };
 935 |           case "sw": return { rMin: cornerR,            cMin: cornerC - lenA + 1, rMax: cornerR + lenB - 1, cMax: cornerC };
 936 |           case "ne": return { rMin: cornerR - lenB + 1, cMin: cornerC,            rMax: cornerR,            cMax: cornerC + lenA - 1 };
 937 |           case "nw": return { rMin: cornerR - lenB + 1, cMin: cornerC - lenA + 1, rMax: cornerR,            cMax: cornerC };
 938 |         }
 939 |       }
 940 | 
 941 |       function lsofaCells(cornerR, cornerC, lenA, lenB, variant) {
 942 |         const out = []; const seen = new Set();
 943 |         const add = (r,c) => { const k=r+","+c; if(!seen.has(k)){seen.add(k);out.push({r,c});} };
 944 |         for (let i = 0; i < lenA; i++) add(cornerR, (variant==="sw"||variant==="nw") ? cornerC-i : cornerC+i);
 945 |         for (let i = 0; i < lenB; i++) add((variant==="ne"||variant==="nw") ? cornerR-i : cornerR+i, cornerC);
 946 |         return out;
 947 |       }
 948 | 
 949 |       function clampLsofaCorner(cornerR, cornerC, lenA, lenB, variant) {
 950 |         const bb = lsofaBBox(cornerR, cornerC, lenA, lenB, variant);
 951 |         let dr=0, dc=0;
 952 |         if (bb.rMin < 0)     dr = -bb.rMin;
 953 |         if (bb.rMax >= SIZE) dr = SIZE - 1 - bb.rMax;
 954 |         if (bb.cMin < 0)     dc = -bb.cMin;
 955 |         if (bb.cMax >= SIZE) dc = SIZE - 1 - bb.cMax;
 956 |         return { cornerR: cornerR+dr, cornerC: cornerC+dc };
 957 |       }
 958 | 
 959 |       function hasConflictL(cornerR, cornerC, lenA, lenB, variant, ignoreId=null) {
 960 |         for (const {r,c} of lsofaCells(cornerR, cornerC, lenA, lenB, variant))
 961 |           for (const tid of tableGrid[r][c]) if (tid !== ignoreId) return true;
 962 |         return false;
 963 |       }
 964 | 
 965 |       function stampLsofa(t) {
 966 |         for (const {r,c} of lsofaCells(t.cornerR, t.cornerC, t.lenA, t.lenB, t.variant)) {
 967 |           cells[r][c].classList.remove("selected","light","dark","preview");
 968 |           cells[r][c].style.backgroundColor = t.color;
 969 |           cells[r][c].style.opacity = "0.85";
 970 |           if (!tableGrid[r][c].includes(t.id)) tableGrid[r][c].push(t.id);
 971 |         }
 972 |       }
 973 | 
 974 |       function eraseLsofa(t) {
 975 |         for (const {r,c} of lsofaCells(t.cornerR, t.cornerC, t.lenA, t.lenB, t.variant)) {
 976 |           tableGrid[r][c] = tableGrid[r][c].filter(id => id !== t.id);
 977 |           if (tableGrid[r][c].length === 0) { resetCell(r,c); }
 978 |           else {
 979 |             const top = tables.find(p => p.id === tableGrid[r][c][tableGrid[r][c].length-1]);
 980 |             if (top) { cells[r][c].style.backgroundColor = top.color; cells[r][c].style.opacity="0.85"; }
 981 |           }
 982 |         }
 983 |       }
 984 | 
 985 |       /** Draw the L polygon onto a canvas context. */
 986 |       function drawLshape(ctx, W, H, lenA, lenB, variant, fillColor, strokeColor, conflict) {
 987 |         ctx.clearRect(0, 0, W, H);
 988 |         ctx.beginPath();
 989 |         switch (variant) {
 990 |           case "se":
 991 |             ctx.moveTo(0,    0);    ctx.lineTo(W,    0);
 992 |             ctx.lineTo(W,    CELL); ctx.lineTo(CELL, CELL);
 993 |             ctx.lineTo(CELL, H);    ctx.lineTo(0,    H);
 994 |             break;
 995 |           case "sw":
 996 |             ctx.moveTo(W,      0);    ctx.lineTo(0,      0);
 997 |             ctx.lineTo(0,      CELL); ctx.lineTo(W-CELL, CELL);
 998 |             ctx.lineTo(W-CELL, H);    ctx.lineTo(W,      H);
 999 |             break;
1000 |           case "ne":
1001 |             ctx.moveTo(0,    H);      ctx.lineTo(W,    H);
1002 |             ctx.lineTo(W,    H-CELL); ctx.lineTo(CELL, H-CELL);
1003 |             ctx.lineTo(CELL, 0);      ctx.lineTo(0,    0);
1004 |             break;
1005 |           case "nw":
1006 |             ctx.moveTo(W,      H);      ctx.lineTo(0,      H);
1007 |             ctx.lineTo(0,      H-CELL); ctx.lineTo(W-CELL, H-CELL);
1008 |             ctx.lineTo(W-CELL, 0);      ctx.lineTo(W,      0);
1009 |             break;
1010 |         }
1011 |         ctx.closePath();
1012 |         ctx.fillStyle   = conflict ? "rgba(255,60,60,0.35)"  : fillColor;
1013 |         ctx.strokeStyle = conflict ? "rgba(255,80,80,0.9)"   : strokeColor;
1014 |         ctx.lineWidth = 2; ctx.fill(); ctx.stroke();
1015 |       }
1016 | 
