 716 |       // R key: if in couch mode, toggle ghostOrientation.
 717 |       //        if a couch is selected, rotate it in-place (snap back if no room).
 718 |       function handleRotate() {
 719 |         if (lsofaMode || (selectedTable && selectedTable.type === "lsofa")) {
 720 |           handleLsofaRotate(); return;
 721 |         }
 722 |         if (couchMode) {
