 732 |       function rotateCouch(t) {
 733 |         const newOrientation = t.orientation === "h" ? "v" : "h";
 734 |         // Pivot around top-left corner: swap (rMax-rMin) ↔ (cMax-cMin)
 735 |         const height = t.rMax - t.rMin; // current row-span minus 1
 736 |         const width  = t.cMax - t.cMin; // current col-span minus 1
 737 |         const newRMax = t.rMin + width;
 738 |         const newCMax = t.cMin + height;
 739 |         // Clamp to board
 740 |         const rMax = Math.min(newRMax, SIZE - 1);
 741 |         const cMax = Math.min(newCMax, SIZE - 1);
 742 |         const rMin = t.rMin;
 743 |         const cMin = t.cMin;
