// ── Rug mode (freeform polyomino, up to 16 cells) ────────────────────────
const RUG_COLORS = [
  "#c0874a","#4aaf8e","#7a6cb8","#c04a8a",
  "#8aae3a","#4a7ac0","#c07a4a","#3abcbc",
];

function toggleRugMode() { if (rugMode) exitRugMode(); else enterRugMode(); }

function enterRugMode() {
  exitCouchMode(); exitChairMode(); exitLsofaMode();
  rugMode = true;
  rugPaintCells = new Set();
  btnRug.style.borderColor = "#c0874a";
  btnRug.style.background  = "#5a3010";
  board.style.cursor = "crosshair";
  updateRugCounter();
  rugCounterEl.style.display = "block";
}

function exitRugMode() {
  if (!rugMode) return;
  rugMode = false;
  // Clear any painted cells
  rugPaintCells.forEach(key => {
    const [r,c] = key.split(",").map(Number);
    cells[r][c].classList.remove("rug-paint","rug-paint-conflict");
  });
  rugPaintCells = new Set();
  btnRug.style.borderColor = "";
  btnRug.style.background  = "";
  board.style.cursor = "crosshair";
  rugCounterEl.style.display = "none";
}

function updateRugCounter() {
  const n = rugPaintCells.size;
  rugCounterEl.textContent = `${n} / ${RUG_MAX_CELLS} cells — Enter to place, Esc to cancel`;
  rugCounterEl.classList.toggle("at-limit", n >= RUG_MAX_CELLS);
}

/** BFS connectivity check — returns true if all cells in `cellSet` are connected. */
function rugIsConnected(cellSet) {
  if (cellSet.size === 0) return true;
  if (cellSet.size === 1) return true;
  const arr = [...cellSet];
  const visited = new Set();
  const queue = [arr[0]];
  visited.add(arr[0]);
  while (queue.length) {
    const key = queue.shift();
    const [r,c] = key.split(",").map(Number);
    for (const [dr,dc] of [[-1,0],[1,0],[0,-1],[0,1]]) {
      const nk = `${r+dr},${c+dc}`;
      if (cellSet.has(nk) && !visited.has(nk)) {
        visited.add(nk); queue.push(nk);
      }
    }
  }
  return visited.size === cellSet.size;
}

/** Returns true if removing `key` from `cellSet` keeps it connected. */
function rugCanRemove(cellSet, key) {
  if (cellSet.size <= 1) return true;
  const remaining = new Set(cellSet); remaining.delete(key);
  return rugIsConnected(remaining);
}

/** Handle a click on cell (r,c) in rug paint mode. */
function rugToggleCell(r, c) {
  const key = `${r},${c}`;
  if (rugPaintCells.has(key)) {
    // Remove if it keeps the shape connected
    if (!rugCanRemove(rugPaintCells, key)) {
      // Flash the cell red briefly to indicate you can't remove it
      cells[r][c].classList.add("rug-paint-conflict");
      setTimeout(() => {
        if (rugPaintCells.has(key)) {
          cells[r][c].classList.remove("rug-paint-conflict");
          cells[r][c].classList.add("rug-paint");
        }
      }, 400);
      return;
    }
    rugPaintCells.delete(key);
    cells[r][c].classList.remove("rug-paint","rug-paint-conflict");
  } else {
    // Add only if (a) size < max, (b) adjacent to existing, (c) cell is free
    if (rugPaintCells.size >= RUG_MAX_CELLS) {
      cells[r][c].classList.add("rug-paint-conflict");
      setTimeout(() => cells[r][c].classList.remove("rug-paint-conflict"), 400);
      return;
    }
    if (tableGrid[r][c].length > 0) {
      cells[r][c].classList.add("rug-paint-conflict");
      setTimeout(() => cells[r][c].classList.remove("rug-paint-conflict"), 400);
      return;
    }
    // Must be adjacent to an existing painted cell (unless first cell)
    if (rugPaintCells.size > 0) {
      const adjacent = [[-1,0],[1,0],[0,-1],[0,1]].some(([dr,dc]) => rugPaintCells.has(`${r+dr},${c+dc}`));
      if (!adjacent) {
        cells[r][c].classList.add("rug-paint-conflict");
        setTimeout(() => cells[r][c].classList.remove("rug-paint-conflict"), 400);
        return;
      }
    }
    rugPaintCells.add(key);
    cells[r][c].classList.add("rug-paint");
  }
  updateRugCounter();
}

board.addEventListener("click", (e) => {
  if (!rugMode) return;
  const cell = e.target.closest(".cell");
  if (!cell) return;
  rugToggleCell(parseInt(cell.dataset.row), parseInt(cell.dataset.col));
});

// ── Rug helpers ───────────────────────────────────────────────────────────
function rugBBox(cellArr) {
  let rMin=SIZE, rMax=0, cMin=SIZE, cMax=0;
  for (const {r,c} of cellArr) {
    if (r<rMin) rMin=r; if (r>rMax) rMax=r;
    if (c<cMin) cMin=c; if (c>cMax) cMax=c;
  }
  return {rMin, rMax, cMin, cMax};
}

/** Return a new cell list offset so bounding-box top-left is (newRMin, newCMin) */
function rugOffsetCells(t, newRMin, newCMin) {
  const dr = newRMin - t.rMin, dc = newCMin - t.cMin;
  return t.cells.map(({r,c}) => ({r: r+dr, c: c+dc}));
}

function hasConflictForRug(cellArr, ignoreId=null) {
  for (const {r,c} of cellArr) {
    if (r<0||r>=SIZE||c<0||c>=SIZE) return true;
    for (const tid of tableGrid[r][c]) {
      if (tid !== ignoreId) return true;
    }
  }
  return false;
}

/** Draw the polyomino onto a canvas context. */
function drawRug(ctx, W, H, cells, rMin, cMin, fillColor, strokeColor) {
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = fillColor;
  ctx.strokeStyle = strokeColor;
  ctx.lineWidth = 1.5;
  for (const {r,c} of cells) {
    const x = (c - cMin) * CELL, y = (r - rMin) * CELL;
    ctx.fillRect(x+0.5, y+0.5, CELL-1, CELL-1);
  }
  // Draw a unified outline using path tracing
  ctx.lineWidth = 2;
  ctx.strokeStyle = strokeColor;
  const cellSet = new Set(cells.map(({r,c}) => `${r},${c}`));
  for (const {r,c} of cells) {
    const x = (c - cMin) * CELL, y = (r - rMin) * CELL;
    // Top edge
    if (!cellSet.has(`${r-1},${c}`)) { ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x+CELL, y); ctx.stroke(); }
    // Bottom edge
    if (!cellSet.has(`${r+1},${c}`)) { ctx.beginPath(); ctx.moveTo(x, y+CELL); ctx.lineTo(x+CELL, y+CELL); ctx.stroke(); }
    // Left edge
    if (!cellSet.has(`${r},${c-1}`)) { ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x, y+CELL); ctx.stroke(); }
    // Right edge
    if (!cellSet.has(`${r},${c+1}`)) { ctx.beginPath(); ctx.moveTo(x+CELL, y); ctx.lineTo(x+CELL, y+CELL); ctx.stroke(); }
  }
}

function stampRug(t) {
  for (const {r,c} of t.cells) {
    cells[r][c].classList.remove("selected","light","dark","preview");
    cells[r][c].style.backgroundColor = t.color;
    cells[r][c].style.opacity = "0.85";
    if (!tableGrid[r][c].includes(t.id)) tableGrid[r][c].push(t.id);
  }
}

function eraseRug(t) {
  for (const {r,c} of t.cells) {
    tableGrid[r][c] = tableGrid[r][c].filter(id => id !== t.id);
    if (tableGrid[r][c].length === 0) { resetCell(r,c); }
    else {
      const top = tables.find(p => p.id === tableGrid[r][c][tableGrid[r][c].length-1]);
      if (top) { cells[r][c].style.backgroundColor = top.color; cells[r][c].style.opacity="0.85"; }
    }
  }
}

function renderRugEl(t) {
  const bb = rugBBox(t.cells);
  t.rMin=bb.rMin; t.rMax=bb.rMax; t.cMin=bb.cMin; t.cMax=bb.cMax;
  const W=(bb.cMax-bb.cMin+1)*CELL, H=(bb.rMax-bb.rMin+1)*CELL;
  t.el.style.left=(bb.cMin*CELL)+"px"; t.el.style.top=(bb.rMin*CELL)+"px";
  t.el.style.width=W+"px"; t.el.style.height=H+"px";
  t.canvas.width=W; t.canvas.height=H;
  drawRug(t.canvas.getContext("2d"), W, H, t.cells, bb.rMin, bb.cMin, t.color+"99", t.color);
}

// ── Place Rug ─────────────────────────────────────────────────────────────
function placeRug() {
  if (!rugMode || rugPaintCells.size === 0) return;
  // Convert to cell array
  const cellArr = [...rugPaintCells].map(k => { const [r,c]=k.split(",").map(Number); return {r,c}; });
  // Final conflict check
  if (hasConflictForRug(cellArr)) {
    rugCounterEl.classList.add("at-limit");
    setTimeout(() => rugCounterEl.classList.remove("at-limit"), 500);
    return;
  }

  const bb = rugBBox(cellArr);
  const color = RUG_COLORS[rugCount % RUG_COLORS.length];
  const id    = tableCount++;
  rugCount++;
  const label = `Rug ${rugCount}`;

  // Clear paint highlights
  rugPaintCells.forEach(key => {
    const [r,c] = key.split(",").map(Number);
    cells[r][c].classList.remove("rug-paint","rug-paint-conflict");
  });
  rugPaintCells = new Set();

  const el = document.createElement("div");
  el.className = "rug-rect";

  const canvas = document.createElement("canvas");
  el.appendChild(canvas);

  const t = {
    id, type: "rug",
    cells: cellArr,
    rMin: bb.rMin, rMax: bb.rMax, cMin: bb.cMin, cMax: bb.cMax,
    color, label, el, canvas,
  };
  tables.push(t);
  renderRugEl(t);
  stampRug(t);
  overlay.appendChild(el);

  el.addEventListener("mousedown", (e) => { if (rugMode) return; onTableMouseDown(e, t); });
  el.addEventListener("click",     (e) => { e.stopPropagation(); if (!rugMode) selectTable(t); });

  // Exit rug mode after placing
  rugMode = false;
  btnRug.style.borderColor = "";
  btnRug.style.background  = "";
  board.style.cursor = "crosshair";
  rugCounterEl.style.display = "none";
}

btnRug.addEventListener("click", toggleRugMode);

