// ── Rug helpers & placement ───────────────────────────────────────────────
function rugBBox(cellArr) {
  let rMin=SIZE, rMax=0, cMin=SIZE, cMax=0;
  for (const {r,c} of cellArr) {
    if (r<rMin) rMin=r; if (r>rMax) rMax=r;
    if (c<cMin) cMin=c; if (c>cMax) cMax=c;
  }
  return {rMin, rMax, cMin, cMax};
}

function rugOffsetCells(t, newRMin, newCMin) {
  const dr = newRMin - t.rMin, dc = newCMin - t.cMin;
  return t.cells.map(({r,c}) => ({r: r+dr, c: c+dc}));
}

function hasConflictForRug(cellArr, ignoreId=null) {
  for (const {r,c} of cellArr) {
    if (r<0||r>=SIZE||c<0||c>=SIZE) return true;
    for (const tid of tableGrid[r][c]) { if (tid !== ignoreId) return true; }
  }
  return false;
}

function drawRug(ctx, W, H, rugCells, rMin, cMin, fillColor, strokeColor) {
  ctx.clearRect(0, 0, W, H);
  const cellSet = new Set(rugCells.map(({r,c}) => `${r},${c}`));
  ctx.fillStyle = fillColor;
  for (const {r,c} of rugCells) {
    const x=(c-cMin)*CELL, y=(r-rMin)*CELL;
    ctx.fillRect(x+0.5, y+0.5, CELL-1, CELL-1);
  }
  ctx.lineWidth = 2; ctx.strokeStyle = strokeColor;
  for (const {r,c} of rugCells) {
    const x=(c-cMin)*CELL, y=(r-rMin)*CELL;
    if (!cellSet.has(`${r-1},${c}`)) { ctx.beginPath(); ctx.moveTo(x,y); ctx.lineTo(x+CELL,y); ctx.stroke(); }
    if (!cellSet.has(`${r+1},${c}`)) { ctx.beginPath(); ctx.moveTo(x,y+CELL); ctx.lineTo(x+CELL,y+CELL); ctx.stroke(); }
    if (!cellSet.has(`${r},${c-1}`)) { ctx.beginPath(); ctx.moveTo(x,y); ctx.lineTo(x,y+CELL); ctx.stroke(); }
    if (!cellSet.has(`${r},${c+1}`)) { ctx.beginPath(); ctx.moveTo(x+CELL,y); ctx.lineTo(x+CELL,y+CELL); ctx.stroke(); }
  }
}

function stampRug(t) {
  for (const {r,c} of t.cells) {
    cells[r][c].classList.remove("selected","light","dark","preview");
    cells[r][c].style.backgroundColor = t.color;
    cells[r][c].style.opacity = "0.85";
    if (!tableGrid[r][c].includes(t.id)) tableGrid[r][c].push(t.id);
  }
}

function eraseRug(t) {
  for (const {r,c} of t.cells) {
    tableGrid[r][c] = tableGrid[r][c].filter(id => id !== t.id);
    if (tableGrid[r][c].length === 0) { resetCell(r,c); }
    else {
      const top = tables.find(p => p.id === tableGrid[r][c][tableGrid[r][c].length-1]);
      if (top) { cells[r][c].style.backgroundColor = top.color; cells[r][c].style.opacity="0.85"; }
    }
  }
}

function renderRugEl(t) {
  const bb = rugBBox(t.cells);
  t.rMin=bb.rMin; t.rMax=bb.rMax; t.cMin=bb.cMin; t.cMax=bb.cMax;
  const W=(bb.cMax-bb.cMin+1)*CELL, H=(bb.rMax-bb.rMin+1)*CELL;
  t.el.style.left=(bb.cMin*CELL)+"px"; t.el.style.top=(bb.rMin*CELL)+"px";
  t.el.style.width=W+"px"; t.el.style.height=H+"px";
  t.canvas.width=W; t.canvas.height=H;
  drawRug(t.canvas.getContext("2d"), W, H, t.cells, bb.rMin, bb.cMin, t.color+"99", t.color);
}

function placeRug() {
  if (!rugMode || rugPaintCells.size === 0) return;
  const cellArr = [...rugPaintCells].map(k => { const [r,c]=k.split(",").map(Number); return {r,c}; });
  if (hasConflictForRug(cellArr)) {
    rugCounterEl.classList.add("at-limit");
    setTimeout(() => rugCounterEl.classList.remove("at-limit"), 500);
    return;
  }
  const bb = rugBBox(cellArr);
  const color = RUG_COLORS[rugCount % RUG_COLORS.length];
  const id = tableCount++;
  rugCount++;

  // Clear paint highlights
  rugPaintCells.forEach(key => {
    const [r,c] = key.split(",").map(Number);
    cells[r][c].classList.remove("rug-paint","rug-paint-conflict");
  });
  rugPaintCells = new Set();

  const el = document.createElement("div");
  el.className = "rug-rect";
  const canvas = document.createElement("canvas");
  el.appendChild(canvas);

  const t = { id, type:"rug", cells:cellArr,
              rMin:bb.rMin, rMax:bb.rMax, cMin:bb.cMin, cMax:bb.cMax,
              color, label:`Rug ${rugCount}`, el, canvas };
  tables.push(t);
  renderRugEl(t);
  stampRug(t);
  overlay.appendChild(el);

  el.addEventListener("mousedown", (e) => { if (rugMode) return; onTableMouseDown(e, t); });
  el.addEventListener("click", (e) => { e.stopPropagation(); if (!rugMode) selectTable(t); });

  // Exit rug mode after placing
  rugMode = false;
  btnRug.style.borderColor = "";
  btnRug.style.background  = "";
  board.style.cursor = "crosshair";
  rugCounterEl.style.display = "none";
}

btnRug.addEventListener("click", toggleRugMode);

// ── Board selection mouse events ─────────────────────────────────────────
board.addEventListener("dragstart", (e) => e.preventDefault());

