412 |       function selPreviewRect(curRow,curCol) {
413 |         const dr1=Math.min(selStartRow,curRow), dr2=Math.max(selStartRow,curRow);
414 |         const dc1=Math.min(selStartCol,curCol), dc2=Math.max(selStartCol,curCol);
415 |         if (!selection) return {rMin:dr1,cMin:dc1,rMax:dr2,cMax:dc2};
