425 |         for (let row=r.rMin;row<=r.rMax;row++) {
426 |           for (let col=r.cMin;col<=r.cMax;col++) {
427 |             if (tableGrid[row][col].length > 0) {
428 |               cells[row][col].classList.add("conflict");
429 |             } else {
430 |               cells[row][col].classList.add("preview");
431 |             }
432 |           }
433 |         }
