435 |         selOverlay.style.left    = (r.cMin * CELL) + "px";
436 |         selOverlay.style.top     = (r.rMin * CELL) + "px";
437 |         selOverlay.style.width   = ((r.cMax - r.cMin + 1) * CELL) + "px";
