443 |       // ── Cell colour helpers ──────────────────────────────────────────────────
444 |       function resetCell(r,c) {
445 |         const cell = cells[r][c];
446 |         cell.style.backgroundColor = "";
447 |         cell.style.opacity = "";
448 |         cell.classList.remove("selected","preview");
449 |         cell.classList.add((r+c)%2===0 ? "light" : "dark");
450 |         tableGrid[r][c] = [];
451 |       }
452 |       function stampTable(t) {
453 |         for (let r=t.rMin;r<=t.rMax;r++) for (let c=t.cMin;c<=t.cMax;c++) {
454 |           const cell = cells[r][c];
455 |           cell.classList.remove("selected","light","dark","preview");
456 |           cell.style.backgroundColor = t.color;
457 |           cell.style.opacity = "0.85";
458 |           if (!tableGrid[r][c].includes(t.id)) tableGrid[r][c].push(t.id);
459 |           if (t.type === "chair") refreshChairBadge(r, c);
460 |         }
461 |       }
462 |       function eraseTable(t) {
463 |         for (let r=t.rMin;r<=t.rMax;r++) for (let c=t.cMin;c<=t.cMax;c++) {
464 |           tableGrid[r][c] = tableGrid[r][c].filter(id => id !== t.id);
465 |           if (tableGrid[r][c].length === 0) {
466 |             resetCell(r, c);
467 |           } else {
468 |             // Repaint with the topmost remaining piece's colour
469 |             const topId = tableGrid[r][c][tableGrid[r][c].length - 1];
470 |             const top   = tables.find(p => p.id === topId);
471 |             if (top) {
472 |               cells[r][c].style.backgroundColor = top.color;
473 |               cells[r][c].style.opacity = "0.85";
474 |             }
475 |             // If there are chairs left here, refresh their badge
476 |             const hasChair = tableGrid[r][c].some(id => {
477 |               const p = tables.find(q => q.id === id);
478 |               return p && p.type === "chair";
479 |             });
480 |             if (hasChair || t.type === "chair") refreshChairBadge(r, c);
481 |           }
482 |         }
483 |       }
484 |       function positionEl(t) {
485 |         t.el.style.left   = (t.cMin * CELL) + "px";
486 |         t.el.style.top    = (t.rMin * CELL) + "px";
487 |         t.el.style.width  = ((t.cMax - t.cMin + 1) * CELL) + "px";
488 |         t.el.style.height = ((t.rMax - t.rMin + 1) * CELL) + "px";
489 |       }
