491 |       // ── Table selection & edit ───────────────────────────────────────────────
492 |       function updateToolbar() {
493 |         btnTable.disabled  = !selection;
494 |         btnEdit.disabled   = !selectedTable;
495 |         btnDelete.disabled = !selectedTable;
496 |       }
497 | 
498 |       function selectTable(t) {
499 |         if (selectedTable) selectedTable.el.classList.remove("table-selected");
500 |         selectedTable = t;

500 |         selectedTable = t;
501 |         if (t) t.el.classList.add("table-selected");
502 |         updateToolbar();
503 |       }
