505 |       function editTable(t) {
506 |         if (!t) return;
507 |         // Save original bounds in case user cancels
508 |         t._editBackup = { rMin: t.rMin, cMin: t.cMin, rMax: t.rMax, cMax: t.cMax };
509 |         editingTable = t;
510 |         // Lift the table off the board into the active selection
511 |         eraseTable(t);
512 |         t.el.style.display = "none";
513 |         // Load its area as the current selection
514 |         selection = { rMin: t.rMin, cMin: t.cMin, rMax: t.rMax, cMax: t.cMax };
515 |         renderSelection();
516 |         selectTable(null);
517 |       }
518 | 
519 |       function cancelEdit() {
520 |         if (!editingTable) return;
521 |         const t = editingTable;
522 |         // Restore original position
523 |         t.rMin = t._editBackup.rMin; t.cMin = t._editBackup.cMin;
524 |         t.rMax = t._editBackup.rMax; t.cMax = t._editBackup.cMax;
525 |         delete t._editBackup;
526 |         stampTable(t);
527 |         positionEl(t);
528 |         t.el.style.display = "";
529 |         editingTable = null;
530 |         // Clear selection
531 |         selection = null;
532 |         clearClass("preview"); clearClass("conflict");
533 |         renderSelection();
534 |       }
535 | 
536 |       function deleteTable(t) {
537 |         if (!t) return;
538 |         // Snapshot chair position before erasing (needed for badge refresh after splice)
539 |         const wasChair = t.type === "chair";
540 |         const chairR = t.rMin, chairC = t.cMin;
541 | 
542 |         // If this table is currently being edited, cancel the edit first
543 |         if (editingTable === t) {
544 |           editingTable = null;
545 |           delete t._editBackup;
546 |           selection = null;
547 |           clearClass("preview"); clearClass("conflict");
548 |         } else {
549 |           if (t.type === "lsofa") eraseLsofa(t);
550 |           else if (t.type === "rug") eraseRug(t);
551 |           else eraseTable(t);
552 |         }
553 |         // Remove overlay element
554 |         if (t.el.parentNode) t.el.parentNode.removeChild(t.el);
555 |         // Remove from tables array
556 |         const idx = tables.indexOf(t);
557 |         if (idx !== -1) tables.splice(idx, 1);
558 |         // If a stacked chair was deleted, refresh the badge now that t is gone from `tables`
559 |         if (wasChair) refreshChairBadge(chairR, chairC);
560 |         // Deselect
561 |         if (selectedTable === t) selectTable(null);
562 |         renderSelection();
563 |       }
