565 |       // ── Conflict detection ───────────────────────────────────────────────────
566 |       // Returns true if the given rect overlaps any piece (optionally ignoring one id).
567 |       function hasConflict(rMin,cMin,rMax,cMax,ignoreId=null) {
568 |         for (let r=rMin;r<=rMax;r++) for (let c=cMin;c<=cMax;c++) {
569 |           for (const tid of tableGrid[r][c]) {
570 |             if (tid !== ignoreId) return true;
571 |           }
572 |         }
573 |         return false;
574 |       }
575 | 
576 |       // Chair-specific conflict: only blocks on non-chair pieces (chairs can stack).
577 |       function hasConflictForChair(row, col, ignoreId=null) {
578 |         for (const tid of tableGrid[row][col]) {
579 |           if (tid === ignoreId) continue;
580 |           const piece = tables.find(t => t.id === tid);
581 |           if (piece && piece.type !== "chair") return true;
582 |         }
583 |         return false;
584 |       }
585 | 
586 |       // Couch-specific conflict: blocks on any other piece — couches cannot stack.
587 |       function hasConflictForCouch(rMin, cMin, rMax, cMax, ignoreId=null) {
588 |         return hasConflict(rMin, cMin, rMax, cMax, ignoreId);
589 |       }
