591 |       // ── Place Table ──────────────────────────────────────────────────────────
592 |       function placeTable() {
593 |         if (!selection) return;
594 |         const { rMin, cMin, rMax, cMax } = selection;
595 |         const ignoreId = editingTable ? editingTable.id : null;
596 | 
597 |         if (hasConflict(rMin,cMin,rMax,cMax,ignoreId)) {
598 |           btnTable.classList.add("conflict");
599 |           setTimeout(() => btnTable.classList.remove("conflict"), 600);
600 |           return;
601 |         }
602 | 
603 |         if (editingTable) {
604 |           // Re-place the edited table with its new bounds
605 |           const t = editingTable;
606 |           editingTable = null;
607 |           delete t._editBackup;
608 |           t.rMin=rMin; t.cMin=cMin; t.rMax=rMax; t.cMax=cMax;
609 |           stampTable(t);
610 |           positionEl(t);
611 |           t.el.style.display = "";
612 |           selection = null;
613 |           renderSelection();
614 |           return;
615 |         }
616 | 
617 |         const color = TABLE_COLORS[tableCount % TABLE_COLORS.length];
618 |         const id    = tableCount++;
619 |         const label = `Table ${id + 1}`;
620 | 
621 |         const el = document.createElement("div");
622 |         el.className = "table-rect";
623 |         el.style.backgroundColor = color + "44";
624 |         el.style.borderColor = color;
625 |         el.textContent = label;
