627 |         const t = { id, rMin, cMin, rMax, cMax, color, label, el };
628 |         tables.push(t);
629 |         positionEl(t);
630 |         stampTable(t);
631 |         overlay.appendChild(el);
632 |         el.addEventListener("mousedown", (e) => onTableMouseDown(e, t));
633 |         el.addEventListener("click",     (e) => { e.stopPropagation(); selectTable(t); });
634 | 
635 |         selection = null;
636 |         renderSelection();
637 |       }
