639 |       btnTable.addEventListener("click", placeTable);
640 |       btnEdit.addEventListener("click", () => editTable(selectedTable));
641 |       btnDelete.addEventListener("click", () => deleteTable(selectedTable));
642 |       document.addEventListener("keydown", (e) => {
643 |         if (e.key==="t"||e.key==="T")      placeTable();
644 |         if (e.key==="e"||e.key==="E")      editTable(selectedTable);
645 |         if (e.key==="d"||e.key==="D")      deleteTable(selectedTable);
646 |         if (e.key==="Escape")              { cancelEdit(); exitCouchMode(); exitChairMode(); exitLsofaMode(); exitRugMode(); }
647 |         if (e.key==="c"||e.key==="C")      toggleCouchMode();
648 |         if (e.key==="h"||e.key==="H")      toggleChairMode();
649 |         if (e.key==="l"||e.key==="L")      toggleLsofaMode();
650 |         if (e.key==="p"||e.key==="P")      toggleRugMode();
651 |         if (e.key==="r"||e.key==="R")      handleRotate();
652 |         if (e.key==="Enter")               placeRug();
653 |       });
