656 |       // ── Couch mode ───────────────────────────────────────────────────────────
657 |       // A couch is always 1 row × 2 cols (minimum 1×2, restricted to 1×n).
658 |       const COUCH_ROWS = 1, COUCH_COLS = 2;
659 |       const COUCH_COLORS = [
660 |         "#7b5ea7","#4a90d9","#2ecc71","#e67e22",
661 |         "#1abc9c","#e74c3c","#9b59b6","#3498db",
662 |       ];
