664 |       function toggleCouchMode() {
665 |         if (couchMode) exitCouchMode();
666 |         else enterCouchMode();
667 |       }
668 | 
669 |       function enterCouchMode() {
670 |         exitChairMode();          // mutually exclusive
671 |         exitLsofaMode();
672 |         exitRugMode();
673 |         couchMode = true;
674 |         btnCouch.style.borderColor = "#b86fc4";
675 |         btnCouch.style.background  = "#5a2d6a";
676 |         board.style.cursor = "none";
677 |       }
678 | 
679 |       function exitCouchMode() {
680 |         if (!couchMode) return;
681 |         couchMode = false;
682 |         ghostOrientation = "h";   // reset to horizontal for next entry
683 |         btnCouch.style.borderColor = "";
684 |         btnCouch.style.background  = "";
685 |         board.style.cursor = "crosshair";
686 |         couchGhostEl.style.display = "none";
687 |       }
688 | 
689 |       function couchDims(orientation) {
690 |         return orientation === "h"
691 |           ? { rows: COUCH_ROWS, cols: COUCH_COLS }
692 |           : { rows: COUCH_COLS, cols: COUCH_ROWS };
693 |       }
694 | 
695 |       function updateCouchGhost(row, col) {
696 |         const { rows, cols } = couchDims(ghostOrientation);
697 |         // Clamp so the ghost stays on board
698 |         const rMin = Math.max(0, Math.min(row, SIZE - rows));
699 |         const cMin = Math.max(0, Math.min(col, SIZE - cols));
700 |         couchGhostEl.style.left    = (cMin * CELL) + "px";
701 |         couchGhostEl.style.top     = (rMin * CELL) + "px";
702 |         couchGhostEl.style.width   = (cols * CELL) + "px";
703 |         couchGhostEl.style.height  = (rows * CELL) + "px";
704 |         couchGhostEl.style.display = "block";
705 |         const conflict = hasConflictForCouch(rMin, cMin, rMin + rows - 1, cMin + cols - 1);
706 |         couchGhostEl.classList.toggle("conflict", conflict);
707 |       }
708 | 
709 |       function placeCouch(row, col) {
710 |         const { rows, cols } = couchDims(ghostOrientation);
711 |         const rMin = Math.max(0, Math.min(row, SIZE - rows));
712 |         const cMin = Math.max(0, Math.min(col, SIZE - cols));
713 |         const rMax = rMin + rows - 1;
714 |         const cMax = cMin + cols - 1;
715 |         if (hasConflictForCouch(rMin, cMin, rMax, cMax)) return;
716 | 
717 |         const color = COUCH_COLORS[couchCount % COUCH_COLORS.length];
718 |         const id    = tableCount++; // share global id counter so drag logic works uniformly
719 |         couchCount++;
720 |         const label = `Couch ${couchCount}`;
721 | 
722 |         const el = document.createElement("div");
723 |         el.className = "couch-rect";
724 |         el.style.backgroundColor = color + "55";
725 |         el.style.borderColor = color;
726 | 
727 |         const labelSpan = document.createElement("span");
728 |         labelSpan.textContent = label;
729 |         el.appendChild(labelSpan);
730 | 
731 |         // Resize handles (visible only when selected)
732 |         const handleA = document.createElement("div");
733 |         const handleB = document.createElement("div");
734 |         handleA.className = "couch-handle";
