 964 |       // ── L-shape sofa ─────────────────────────────────────────────────────────
 965 |       // An L-sofa is defined by:
 966 |       //   corner:  (cornerR, cornerC) — the inner corner cell
 967 |       //   lenA:    horizontal arm length (≥ 2)
 968 |       //   lenB:    vertical arm length   (≥ 2)
 969 |       //   variant: "se" | "sw" | "ne" | "nw"
 970 |       //
 971 |       //  "se": H arm → right, V arm → down   (corner = top-left  of bbox)
 972 |       //  "sw": H arm → left,  V arm → down   (corner = top-right)
 973 |       //  "ne": H arm → right, V arm → up     (corner = bottom-left)
 974 |       //  "nw": H arm → left,  V arm → up     (corner = bottom-right)
 975 | 
 976 |       const LSOFA_COLORS = [
 977 |         "#c0703c","#3c8fc0","#7ac03c","#c03c8a",
 978 |         "#3cc09a","#c0b03c","#803cc0","#c05a3c",
 979 |       ];
 980 |       const LSOFA_VARIANT_CYCLE = ["se","sw","nw","ne"];
