 982 |       function lsofaBBox(cornerR, cornerC, lenA, lenB, variant) {
 983 |         switch (variant) {
 984 |           case "se": return { rMin: cornerR,            cMin: cornerC,            rMax: cornerR + lenB - 1, cMax: cornerC + lenA - 1 };
 985 |           case "sw": return { rMin: cornerR,            cMin: cornerC - lenA + 1, rMax: cornerR + lenB - 1, cMax: cornerC };
 986 |           case "ne": return { rMin: cornerR - lenB + 1, cMin: cornerC,            rMax: cornerR,            cMax: cornerC + lenA - 1 };
 987 |           case "nw": return { rMin: cornerR - lenB + 1, cMin: cornerC - lenA + 1, rMax: cornerR,            cMax: cornerC };
 988 |         }
 989 |       }
 990 | 
 991 |       function lsofaCells(cornerR, cornerC, lenA, lenB, variant) {
 992 |         const out = []; const seen = new Set();
 993 |         const add = (r,c) => { const k=r+","+c; if(!seen.has(k)){seen.add(k);out.push({r,c});} };
 994 |         for (let i = 0; i < lenA; i++) add(cornerR, (variant==="sw"||variant==="nw") ? cornerC-i : cornerC+i);
 995 |         for (let i = 0; i < lenB; i++) add((variant==="ne"||variant==="nw") ? cornerR-i : cornerR+i, cornerC);
 996 |         return out;
 997 |       }
 998 | 
 999 |       function clampLsofaCorner(cornerR, cornerC, lenA, lenB, variant) {
1000 |         const bb = lsofaBBox(cornerR, cornerC, lenA, lenB, variant);
1001 |         let dr=0, dc=0;
1002 |         if (bb.rMin < 0)     dr = -bb.rMin;
1003 |         if (bb.rMax >= SIZE) dr = SIZE - 1 - bb.rMax;
1004 |         if (bb.cMin < 0)     dc = -bb.cMin;
1005 |         if (bb.cMax >= SIZE) dc = SIZE - 1 - bb.cMax;
1006 |         return { cornerR: cornerR+dr, cornerC: cornerC+dc };
1007 |       }
1008 | 
1009 |       function hasConflictL(cornerR, cornerC, lenA, lenB, variant, ignoreId=null) {
1010 |         for (const {r,c} of lsofaCells(cornerR, cornerC, lenA, lenB, variant))
1011 |           for (const tid of tableGrid[r][c]) if (tid !== ignoreId) return true;
1012 |         return false;
1013 |       }
