1015 |       function stampLsofa(t) {
1016 |         for (const {r,c} of lsofaCells(t.cornerR, t.cornerC, t.lenA, t.lenB, t.variant)) {
1017 |           cells[r][c].classList.remove("selected","light","dark","preview");
1018 |           cells[r][c].style.backgroundColor = t.color;
1019 |           cells[r][c].style.opacity = "0.85";
1020 |           if (!tableGrid[r][c].includes(t.id)) tableGrid[r][c].push(t.id);
1021 |         }
1022 |       }
1023 | 
1024 |       function eraseLsofa(t) {
1025 |         for (const {r,c} of lsofaCells(t.cornerR, t.cornerC, t.lenA, t.lenB, t.variant)) {
1026 |           tableGrid[r][c] = tableGrid[r][c].filter(id => id !== t.id);
1027 |           if (tableGrid[r][c].length === 0) { resetCell(r,c); }
1028 |           else {
1029 |             const top = tables.find(p => p.id === tableGrid[r][c][tableGrid[r][c].length-1]);
1030 |             if (top) { cells[r][c].style.backgroundColor = top.color; cells[r][c].style.opacity="0.85"; }
