1035 |       /** Draw the L polygon onto a canvas context. */
1036 |       function drawLshape(ctx, W, H, lenA, lenB, variant, fillColor, strokeColor, conflict) {
1037 |         ctx.clearRect(0, 0, W, H);
1038 |         ctx.beginPath();
1039 |         switch (variant) {
1040 |           case "se":
1041 |             ctx.moveTo(0,    0);    ctx.lineTo(W,    0);
1042 |             ctx.lineTo(W,    CELL); ctx.lineTo(CELL, CELL);
1043 |             ctx.lineTo(CELL, H);    ctx.lineTo(0,    H);
1044 |             break;
1045 |           case "sw":
1046 |             ctx.moveTo(W,      0);    ctx.lineTo(0,      0);
1047 |             ctx.lineTo(0,      CELL); ctx.lineTo(W-CELL, CELL);
1048 |             ctx.lineTo(W-CELL, H);    ctx.lineTo(W,      H);
1049 |             break;
1050 |           case "ne":
1051 |             ctx.moveTo(0,    H);      ctx.lineTo(W,    H);
1052 |             ctx.lineTo(W,    H-CELL); ctx.lineTo(CELL, H-CELL);
1053 |             ctx.lineTo(CELL, 0);      ctx.lineTo(0,    0);
1054 |             break;
1055 |           case "nw":
1056 |             ctx.moveTo(W,      H);      ctx.lineTo(0,      H);
1057 |             ctx.lineTo(0,      H-CELL); ctx.lineTo(W-CELL, H-CELL);
1058 |             ctx.lineTo(W-CELL, 0);      ctx.lineTo(W,      0);
1059 |             break;
1060 |         }
1061 |         ctx.closePath();
1062 |         ctx.fillStyle   = conflict ? "rgba(255,60,60,0.35)"  : fillColor;
1063 |         ctx.strokeStyle = conflict ? "rgba(255,80,80,0.9)"   : strokeColor;
