// ── Rotation dispatcher ──────────────────────────────────────────────────
// R key: rotates the selected piece (or toggles ghost orientation in placement modes).
function handleRotate() {
  // L-sofa mode or selected L-sofa
  if (lsofaMode || (selectedTable && selectedTable.type === "lsofa")) {
    handleLsofaRotate(); return;
  }
  // Couch placement ghost
  if (couchMode) {
    ghostOrientation = ghostOrientation === "h" ? "v" : "h";
    couchGhostEl.style.display = "none";
    return;
  }
  if (!selectedTable) return;
  if (selectedTable.type === "couch")  { rotateCouch(selectedTable);  return; }
  if (selectedTable.type === "table")  { rotateTable(selectedTable);  return; }
  if (selectedTable.type === "rug")    { rotateRug(selectedTable);    return; }
  // chair is 1×1 — no rotation needed
}

function rotateCouch(t) {
  const newOrientation = t.orientation === "h" ? "v" : "h";
  // Pivot around top-left corner: swap (rMax-rMin) ↔ (cMax-cMin)
  const height = t.rMax - t.rMin; // current row-span minus 1
  const width  = t.cMax - t.cMin; // current col-span minus 1
  const newRMax = t.rMin + width;
  const newCMax = t.cMin + height;
  // Clamp to board
  const rMax = Math.min(newRMax, SIZE - 1);
  const cMax = Math.min(newCMax, SIZE - 1);
  const rMin = t.rMin;
  const cMin = t.cMin;
  // Check for conflicts (ignoring self)
  if (hasConflictForCouch(rMin, cMin, rMax, cMax, t.id)) return;
  eraseTable(t);
  t.rMax = rMax;
  t.cMax = cMax;
  t.orientation = newOrientation;
  stampTable(t);
  positionEl(t);
  applyHandleClasses(t);
}

/** Rotate a plain rectangular table 90° CW around its top-left corner. */
function rotateTable(t) {
  const h = t.rMax - t.rMin;
  const w = t.cMax - t.cMin;
  const newRMax = Math.min(t.rMin + w, SIZE - 1);
  const newCMax = Math.min(t.cMin + h, SIZE - 1);
  if (hasConflict(t.rMin, t.cMin, newRMax, newCMax, t.id)) return;
  eraseTable(t);
  t.rMax = newRMax;
  t.cMax = newCMax;
  stampTable(t);
  positionEl(t);
}

/** Rotate a rug's cells 90° CW, keeping bounding-box top-left fixed. */
function rotateRug(t) {
  const H = t.rMax - t.rMin + 1; // current bbox height
  // 90° CW around top-left: (dr, dc) → (dc, H-1-dr)
  const rotated = t.cells.map(({r, c}) => {
    const dr = r - t.rMin, dc = c - t.cMin;
    return { r: t.rMin + dc, c: t.cMin + (H - 1 - dr) };
  });
  // Clamp so we stay on the board
  const bb = rugBBox(rotated);
  const dr = Math.max(0, -bb.rMin) + Math.min(0, SIZE - 1 - bb.rMax);
  const dc = Math.max(0, -bb.cMin) + Math.min(0, SIZE - 1 - bb.cMax);
  const clamped = rotated.map(({r, c}) => ({ r: r + dr, c: c + dc }));
  if (hasConflictForRug(clamped, t.id)) return;
  eraseRug(t);
  t.cells = clamped;
  stampRug(t);
  renderRugEl(t);
}

