/** Rotate a plain rectangular table 90° CW around its top-left corner. */
function rotateTable(t) {
  const h = t.rMax - t.rMin; // span in rows (0-based delta)
  const w = t.cMax - t.cMin; // span in cols (0-based delta)
  // After CW rotation, rows←cols and cols←rows
  const newRowSpan = w, newColSpan = h; // 0-based deltas
  const newRows = newRowSpan + 1, newCols = newColSpan + 1;
  // Enforce min/max bounds — skip rotation if it would violate them
  if (newRows < TABLE_MIN_ROWS || newCols < TABLE_MIN_COLS) return;
  if (newRows > TABLE_MAX_ROWS || newCols > TABLE_MAX_COLS) return;
  const newRMax = Math.min(t.rMin + newRowSpan, SIZE - 1);
  const newCMax = Math.min(t.cMin + newColSpan, SIZE - 1);
  if (hasConflict(t.rMin, t.cMin, newRMax, newCMax, t.id)) return;
  eraseTable(t);
  t.rMax = newRMax;
  t.cMax = newCMax;
  stampTable(t);
  positionEl(t);
}

