321 |     <script>
322 |       const CELL = 12, SIZE = 64;
323 |       const board     = document.getElementById("board");
324 |       const overlay   = document.getElementById("overlay");
325 |       const selOverlay = document.getElementById("selection-overlay");
326 |       const btnTable  = document.getElementById("btn-table");
327 |       const btnCouch  = document.getElementById("btn-couch");
328 |       const btnLsofa  = document.getElementById("btn-lsofa");
329 |       const btnChair  = document.getElementById("btn-chair");
330 |       const btnRug    = document.getElementById("btn-rug");
331 |       const btnEdit   = document.getElementById("btn-edit");
332 |       const btnDelete = document.getElementById("btn-delete");
333 |       const boardWrap = document.getElementById("board-wrap");
334 |       const couchGhostEl = document.getElementById("couch-ghost");
335 |       const chairGhostEl = document.getElementById("chair-ghost");
336 |       const lsofaGhostEl = document.getElementById("lsofa-ghost");
337 |       const lsofaGhostCanvas = document.getElementById("lsofa-ghost-canvas");
338 |       const rugCounterEl = document.getElementById("rug-counter");
339 | 
340 |       const TABLE_COLORS = [
341 |         "#e07b54","#5b9bd5","#e8a838","#8e6bbf",
342 |         "#4caf8a","#d95f8a","#6ab04c","#c0392b",
343 |       ];
344 | 
345 |       // ── State ────────────────────────────────────────────────────────────────
346 |       let tableCount = 0;
347 |       const tables    = [];   // { id, rMin,cMin,rMax,cMax, color, label, el }
348 |       const tableGrid = [];   // tableGrid[row][col] = array of piece ids occupying that cell
349 |       let selectedTable = null;   // table currently clicked/focused
350 |       let editingTable  = null;   // table lifted into edit mode
351 | 
352 |       let couchCount = 0;
353 |       let couchMode  = false;     // true while couch-placement is active
354 |       let ghostOrientation = "h"; // "h" or "v" — orientation of the next couch to be placed
355 | 
356 |       let chairCount = 0;
357 |       let chairMode  = false;
358 | 
359 |       let lsofaCount = 0;
360 |       let lsofaMode  = false;
361 |       // Variants: "se" "sw" "ne" "nw" — which direction the two arms extend from the corner
362 |       let lsofaVariant = "se";
363 |       // Ghost arm lengths (editable via handles during placement ghost drag)
364 |       let lsofaGhostLenA = 3; // horizontal arm (min 2)
365 |       let lsofaGhostLenB = 3; // vertical arm   (min 2)
366 | 
367 |       let rugCount = 0;
368 |       let rugMode  = false;
369 |       const RUG_MAX_CELLS = 16;
370 |       // rugPaintCells: Set of "r,c" strings currently painted in rug mode
371 |       let rugPaintCells = new Set();
372 | 
373 |       // ── Build cell grid ──────────────────────────────────────────────────────
374 |       const cells = [];
375 |       for (let row = 0; row < SIZE; row++) {
376 |         cells[row] = []; tableGrid[row] = [];
377 |         for (let col = 0; col < SIZE; col++) {
378 |           const cell = document.createElement("div");
379 |           cell.classList.add("cell");
380 |           cell.classList.add((row + col) % 2 === 0 ? "light" : "dark");
381 |           cell.dataset.row = row; cell.dataset.col = col;
382 |           cells[row][col] = cell; tableGrid[row][col] = [];
383 |           board.appendChild(cell);
384 |         }
385 |       }
386 | 
387 |       // ── Selection helpers ────────────────────────────────────────────────────
388 |       let selection = null;
389 |       let isSelecting = false, selStartRow = null, selStartCol = null;
390 | 
391 |       function clearClass(cls) {
392 |         board.querySelectorAll("." + cls).forEach(c => c.classList.remove(cls));
393 |       }
394 |       function paintRect(r1,c1,r2,c2,cls) {
395 |         for (let r=r1;r<=r2;r++) for (let c=c1;c<=c2;c++) cells[r][c].classList.add(cls);
396 |       }
397 |       function renderSelection() {
398 |         clearClass("selected");
399 |         if (selection) {
400 |           paintRect(selection.rMin,selection.cMin,selection.rMax,selection.cMax,"selected");

400 |           paintRect(selection.rMin,selection.cMin,selection.rMax,selection.cMax,"selected");
401 |           selOverlay.style.left    = (selection.cMin * CELL) + "px";
402 |           selOverlay.style.top     = (selection.rMin * CELL) + "px";
403 |           selOverlay.style.width   = ((selection.cMax - selection.cMin + 1) * CELL) + "px";
404 |           selOverlay.style.height  = ((selection.rMax - selection.rMin + 1) * CELL) + "px";
405 |           selOverlay.style.display = "block";
406 |         } else {
407 |           selOverlay.style.display = "none";
408 |         }
409 |         btnTable.disabled = !selection;
410 |         btnEdit.disabled  = !selectedTable;
411 |       }
412 |       function selPreviewRect(curRow,curCol) {
413 |         const dr1=Math.min(selStartRow,curRow), dr2=Math.max(selStartRow,curRow);
414 |         const dc1=Math.min(selStartCol,curCol), dc2=Math.max(selStartCol,curCol);
415 |         let raw;
416 |         if (!selection) raw = {rMin:dr1,cMin:dc1,rMax:dr2,cMax:dc2};
417 |         else raw = {
418 |           rMin:Math.min(selection.rMin,dr1), cMin:Math.min(selection.cMin,dc1),
419 |           rMax:Math.max(selection.rMax,dr2), cMax:Math.max(selection.cMax,dc2),
420 |         };
421 |         const { rMin, cMin, rMax, cMax } = raw;
422 |         return clampTableSelection(rMin, cMin, rMax, cMax);
423 |       }
424 |       function applySelPreview(curRow,curCol) {
425 |         clearClass("preview");
426 |         clearClass("conflict");
427 |         const r = selPreviewRect(curRow,curCol);
428 |         for (let row=r.rMin;row<=r.rMax;row++) {
429 |           for (let col=r.cMin;col<=r.cMax;col++) {
430 |             if (tableGrid[row][col].length > 0) {
431 |               cells[row][col].classList.add("conflict");
432 |             } else {
433 |               cells[row][col].classList.add("preview");
434 |             }
435 |           }
436 |         }
437 |         // Keep dotted selection outline tracking the live preview rect
438 |         selOverlay.style.left    = (r.cMin * CELL) + "px";
439 |         selOverlay.style.top     = (r.rMin * CELL) + "px";
440 |         selOverlay.style.width   = ((r.cMax - r.cMin + 1) * CELL) + "px";
441 |         selOverlay.style.height  = ((r.rMax - r.rMin + 1) * CELL) + "px";
442 |         selOverlay.style.display = "block";
443 |       }
444 | 
445 | 
446 |       // ── Cell colour helpers ──────────────────────────────────────────────────
447 |       function resetCell(r,c) {
448 |         const cell = cells[r][c];
449 |         cell.style.backgroundColor = "";
450 |         cell.style.opacity = "";
451 |         cell.classList.remove("selected","preview");
452 |         cell.classList.add((r+c)%2===0 ? "light" : "dark");
453 |         tableGrid[r][c] = [];
454 |       }
455 |       function stampTable(t) {
456 |         for (let r=t.rMin;r<=t.rMax;r++) for (let c=t.cMin;c<=t.cMax;c++) {
457 |           const cell = cells[r][c];
458 |           cell.classList.remove("selected","light","dark","preview");
459 |           cell.style.backgroundColor = t.color;
460 |           cell.style.opacity = "0.85";
461 |           if (!tableGrid[r][c].includes(t.id)) tableGrid[r][c].push(t.id);
462 |           if (t.type === "chair") refreshChairBadge(r, c);
463 |         }
464 |       }
465 |       function eraseTable(t) {
466 |         for (let r=t.rMin;r<=t.rMax;r++) for (let c=t.cMin;c<=t.cMax;c++) {
467 |           tableGrid[r][c] = tableGrid[r][c].filter(id => id !== t.id);
468 |           if (tableGrid[r][c].length === 0) {
469 |             resetCell(r, c);
470 |           } else {
471 |             // Repaint with the topmost remaining piece's colour
472 |             const topId = tableGrid[r][c][tableGrid[r][c].length - 1];
473 |             const top   = tables.find(p => p.id === topId);
474 |             if (top) {
475 |               cells[r][c].style.backgroundColor = top.color;
476 |               cells[r][c].style.opacity = "0.85";
477 |             }
478 |             // If there are chairs left here, refresh their badge
479 |             const hasChair = tableGrid[r][c].some(id => {
480 |               const p = tables.find(q => q.id === id);
481 |               return p && p.type === "chair";
482 |             });
483 |             if (hasChair || t.type === "chair") refreshChairBadge(r, c);
484 |           }
485 |         }
486 |       }
487 |       function positionEl(t) {
488 |         t.el.style.left   = (t.cMin * CELL) + "px";
489 |         t.el.style.top    = (t.rMin * CELL) + "px";
490 |         t.el.style.width  = ((t.cMax - t.cMin + 1) * CELL) + "px";
491 |         t.el.style.height = ((t.rMax - t.rMin + 1) * CELL) + "px";
492 |       }
493 | 
494 |       // ── Table selection & edit ───────────────────────────────────────────────
495 |       function updateToolbar() {
496 |         btnTable.disabled  = !selection;
497 |         btnEdit.disabled   = !selectedTable;
498 |         btnDelete.disabled = !selectedTable;
499 |       }
500 | 
501 |       function selectTable(t) {
502 |         if (selectedTable) selectedTable.el.classList.remove("table-selected");
503 |         selectedTable = t;
504 |         if (t) t.el.classList.add("table-selected");
505 |         updateToolbar();
506 |       }
507 | 
508 |       function editTable(t) {
509 |         if (!t) return;
510 |         // Save original bounds in case user cancels
511 |         t._editBackup = { rMin: t.rMin, cMin: t.cMin, rMax: t.rMax, cMax: t.cMax };
512 |         editingTable = t;
513 |         // Lift the table off the board into the active selection
514 |         eraseTable(t);
515 |         t.el.style.display = "none";
516 |         // Load its area as the current selection
517 |         selection = { rMin: t.rMin, cMin: t.cMin, rMax: t.rMax, cMax: t.cMax };
518 |         renderSelection();
519 |         selectTable(null);
520 |       }
521 | 
522 |       function cancelEdit() {
523 |         if (!editingTable) return;
524 |         const t = editingTable;
525 |         // Restore original position
526 |         t.rMin = t._editBackup.rMin; t.cMin = t._editBackup.cMin;
527 |         t.rMax = t._editBackup.rMax; t.cMax = t._editBackup.cMax;
528 |         delete t._editBackup;
529 |         stampTable(t);
530 |         positionEl(t);
531 |         t.el.style.display = "";
532 |         editingTable = null;
533 |         // Clear selection
534 |         selection = null;
535 |         clearClass("preview"); clearClass("conflict");
536 |         renderSelection();
537 |       }
538 | 
539 |       function deleteTable(t) {
540 |         if (!t) return;
541 |         // Snapshot chair position before erasing (needed for badge refresh after splice)
542 |         const wasChair = t.type === "chair";
543 |         const chairR = t.rMin, chairC = t.cMin;
544 | 
545 |         // If this table is currently being edited, cancel the edit first
546 |         if (editingTable === t) {
547 |           editingTable = null;
548 |           delete t._editBackup;
549 |           selection = null;
550 |           clearClass("preview"); clearClass("conflict");
551 |         } else {
552 |           if (t.type === "lsofa") eraseLsofa(t);
553 |           else if (t.type === "rug") eraseRug(t);
554 |           else eraseTable(t);
555 |         }
556 |         // Remove overlay element
557 |         if (t.el.parentNode) t.el.parentNode.removeChild(t.el);
558 |         // Remove from tables array
559 |         const idx = tables.indexOf(t);
560 |         if (idx !== -1) tables.splice(idx, 1);
561 |         // If a stacked chair was deleted, refresh the badge now that t is gone from `tables`
562 |         if (wasChair) refreshChairBadge(chairR, chairC);
563 |         // Deselect
564 |         if (selectedTable === t) selectTable(null);
565 |         renderSelection();
566 |       }
567 | 
568 |       // ── Conflict detection ───────────────────────────────────────────────────
569 |       // Returns true if the given rect overlaps any piece (optionally ignoring one id).
570 |       function hasConflict(rMin,cMin,rMax,cMax,ignoreId=null) {
571 |         for (let r=rMin;r<=rMax;r++) for (let c=cMin;c<=cMax;c++) {
572 |           for (const tid of tableGrid[r][c]) {
573 |             if (tid !== ignoreId) return true;
574 |           }
575 |         }
576 |         return false;
577 |       }
578 | 
579 |       // Chair-specific conflict: only blocks on non-chair pieces (chairs can stack).
580 |       function hasConflictForChair(row, col, ignoreId=null) {
581 |         for (const tid of tableGrid[row][col]) {
582 |           if (tid === ignoreId) continue;
583 |           const piece = tables.find(t => t.id === tid);
584 |           if (piece && piece.type !== "chair") return true;
585 |         }
586 |         return false;
587 |       }
588 | 
589 |       // Couch-specific conflict: blocks on any other piece — couches cannot stack.
590 |       function hasConflictForCouch(rMin, cMin, rMax, cMax, ignoreId=null) {
591 |         return hasConflict(rMin, cMin, rMax, cMax, ignoreId);
592 |       }
593 | 
594 |       // ── Place Table ──────────────────────────────────────────────────────────
595 |       const TABLE_MIN_ROWS = 2, TABLE_MIN_COLS = 3;
596 |       const TABLE_MAX_ROWS = 16, TABLE_MAX_COLS = 24;
597 | 
598 |       /** Enforce table size limits on a raw selection rect. Returns clamped rect. */
599 |       function clampTableSelection(rMin, cMin, rMax, cMax) {
600 |         const rows = rMax - rMin + 1, cols = cMax - cMin + 1;
601 |         // Enforce minimum
602 |         const r2 = Math.min(rMin + Math.max(rows, TABLE_MIN_ROWS) - 1, SIZE - 1);
603 |         const c2 = Math.min(cMin + Math.max(cols, TABLE_MIN_COLS) - 1, SIZE - 1);
604 |         // Enforce maximum
605 |         const r3 = Math.min(r2, rMin + TABLE_MAX_ROWS - 1);
606 |         const c3 = Math.min(c2, cMin + TABLE_MAX_COLS - 1);
607 |         return { rMin, cMin, rMax: r3, cMax: c3 };
608 |       }
609 | 
610 |       function placeTable() {
611 |         if (!selection) return;
612 |         const { rMin, cMin, rMax, cMax } = selection;
613 |         const ignoreId = editingTable ? editingTable.id : null;
614 | 
615 |         if (hasConflict(rMin,cMin,rMax,cMax,ignoreId)) {
616 |           btnTable.classList.add("conflict");
617 |           setTimeout(() => btnTable.classList.remove("conflict"), 600);
618 |           return;
619 |         }
620 | 
621 |         if (editingTable) {
622 |           // Re-place the edited table with its new bounds
623 |           const t = editingTable;
624 |           editingTable = null;
625 |           delete t._editBackup;
626 |           t.rMin=rMin; t.cMin=cMin; t.rMax=rMax; t.cMax=cMax;
627 |           stampTable(t);
628 |           positionEl(t);
629 |           t.el.style.display = "";
630 |           selection = null;
631 |           renderSelection();
632 |           return;
633 |         }
634 | 
635 |         const color = TABLE_COLORS[tableCount % TABLE_COLORS.length];
636 |         const id    = tableCount++;
637 |         const label = `Table ${id + 1}`;
638 | 
639 |         const el = document.createElement("div");
640 |         el.className = "table-rect";
641 |         el.style.backgroundColor = color + "44";
642 |         el.style.borderColor = color;
643 |         el.textContent = label;
644 | 
645 |         const t = { id, rMin, cMin, rMax, cMax, color, label, el };
646 |         tables.push(t);
647 |         positionEl(t);
648 |         stampTable(t);
649 |         overlay.appendChild(el);
650 |         el.addEventListener("mousedown", (e) => onTableMouseDown(e, t));
651 |         el.addEventListener("click",     (e) => { e.stopPropagation(); selectTable(t); });
652 | 
653 |         selection = null;
654 |         renderSelection();
655 |       }
656 | 
657 |       btnTable.addEventListener("click", placeTable);
658 |       btnEdit.addEventListener("click", () => editTable(selectedTable));
