 825 |       /** Rotate a plain rectangular table 90° CW around its top-left corner. */
 826 |       function rotateTable(t) {
 827 |         const h = t.rMax - t.rMin; // span in rows (0-based delta)
 828 |         const w = t.cMax - t.cMin; // span in cols (0-based delta)
 829 |         // After CW rotation, rows←cols and cols←rows
 830 |         const newRowSpan = w, newColSpan = h; // 0-based deltas
 831 |         const newRows = newRowSpan + 1, newCols = newColSpan + 1;
 832 |         // Enforce min/max bounds — skip rotation if it would violate them
 833 |         if (newRows < TABLE_MIN_ROWS || newCols < TABLE_MIN_COLS) return;
 834 |         if (newRows > TABLE_MAX_ROWS || newCols > TABLE_MAX_COLS) return;
 835 |         const newRMax = Math.min(t.rMin + newRowSpan, SIZE - 1);
 836 |         const newCMax = Math.min(t.cMin + newColSpan, SIZE - 1);
 837 |         if (hasConflict(t.rMin, t.cMin, newRMax, newCMax, t.id)) return;
 838 |         eraseTable(t);
 839 |         t.rMax = newRMax;
 840 |         t.cMax = newCMax;
 841 |         stampTable(t);
 842 |         positionEl(t);
