1025 |       // ── L-shape sofa ─────────────────────────────────────────────────────────
1026 |       // An L-sofa is defined by:
1027 |       //   corner:  (cornerR, cornerC) — the inner corner cell
1028 |       //   lenA:    horizontal arm length (≥ 2)
1029 |       //   lenB:    vertical arm length   (≥ 2)
1030 |       //   variant: "se" | "sw" | "ne" | "nw"
1031 |       //
1032 |       //  "se": H arm → right, V arm → down   (corner = top-left  of bbox)
1033 |       //  "sw": H arm → left,  V arm → down   (corner = top-right)
1034 |       //  "ne": H arm → right, V arm → up     (corner = bottom-left)
1035 |       //  "nw": H arm → left,  V arm → up     (corner = bottom-right)
1036 | 
1037 |       const LSOFA_COLORS = [
1038 |         "#c0703c","#3c8fc0","#7ac03c","#c03c8a",
1039 |         "#3cc09a","#c0b03c","#803cc0","#c05a3c",
1040 |       ];
1041 |       const LSOFA_VARIANT_CYCLE = ["se","sw","nw","ne"];
1042 | 
1043 |       function lsofaBBox(cornerR, cornerC, lenA, lenB, variant) {
1044 |         switch (variant) {
1045 |           case "se": return { rMin: cornerR,            cMin: cornerC,            rMax: cornerR + lenB - 1, cMax: cornerC + lenA - 1 };
1046 |           case "sw": return { rMin: cornerR,            cMin: cornerC - lenA + 1, rMax: cornerR + lenB - 1, cMax: cornerC };
1047 |           case "ne": return { rMin: cornerR - lenB + 1, cMin: cornerC,            rMax: cornerR,            cMax: cornerC + lenA - 1 };
1048 |           case "nw": return { rMin: cornerR - lenB + 1, cMin: cornerC - lenA + 1, rMax: cornerR,            cMax: cornerC };
1049 |         }
1050 |       }
1051 | 
1052 |       function lsofaCells(cornerR, cornerC, lenA, lenB, variant) {
1053 |         const out = []; const seen = new Set();
1054 |         const add = (r,c) => { const k=r+","+c; if(!seen.has(k)){seen.add(k);out.push({r,c});} };
1055 |         for (let i = 0; i < lenA; i++) add(cornerR, (variant==="sw"||variant==="nw") ? cornerC-i : cornerC+i);
1056 |         for (let i = 0; i < lenB; i++) add((variant==="ne"||variant==="nw") ? cornerR-i : cornerR+i, cornerC);
1057 |         return out;
1058 |       }
1059 | 
1060 |       function clampLsofaCorner(cornerR, cornerC, lenA, lenB, variant) {
1061 |         const bb = lsofaBBox(cornerR, cornerC, lenA, lenB, variant);
1062 |         let dr=0, dc=0;
1063 |         if (bb.rMin < 0)     dr = -bb.rMin;
1064 |         if (bb.rMax >= SIZE) dr = SIZE - 1 - bb.rMax;
1065 |         if (bb.cMin < 0)     dc = -bb.cMin;
1066 |         if (bb.cMax >= SIZE) dc = SIZE - 1 - bb.cMax;
1067 |         return { cornerR: cornerR+dr, cornerC: cornerC+dc };
1068 |       }
1069 | 
1070 |       function hasConflictL(cornerR, cornerC, lenA, lenB, variant, ignoreId=null) {
1071 |         for (const {r,c} of lsofaCells(cornerR, cornerC, lenA, lenB, variant))
1072 |           for (const tid of tableGrid[r][c]) if (tid !== ignoreId) return true;
1073 |         return false;
1074 |       }
1075 | 
1076 |       function stampLsofa(t) {
1077 |         for (const {r,c} of lsofaCells(t.cornerR, t.cornerC, t.lenA, t.lenB, t.variant)) {
1078 |           cells[r][c].classList.remove("selected","light","dark","preview");
1079 |           cells[r][c].style.backgroundColor = t.color;
1080 |           cells[r][c].style.opacity = "0.85";
1081 |           if (!tableGrid[r][c].includes(t.id)) tableGrid[r][c].push(t.id);
1082 |         }
1083 |       }
1084 | 
1085 |       function eraseLsofa(t) {
1086 |         for (const {r,c} of lsofaCells(t.cornerR, t.cornerC, t.lenA, t.lenB, t.variant)) {
1087 |           tableGrid[r][c] = tableGrid[r][c].filter(id => id !== t.id);
1088 |           if (tableGrid[r][c].length === 0) { resetCell(r,c); }
1089 |           else {
1090 |             const top = tables.find(p => p.id === tableGrid[r][c][tableGrid[r][c].length-1]);
1091 |             if (top) { cells[r][c].style.backgroundColor = top.color; cells[r][c].style.opacity="0.85"; }
1092 |           }
1093 |         }
1094 |       }
