1096 |       /** Draw the L polygon onto a canvas context. */
1097 |       function drawLshape(ctx, W, H, lenA, lenB, variant, fillColor, strokeColor, conflict) {
1098 |         ctx.clearRect(0, 0, W, H);
1099 |         ctx.beginPath();
1100 |         switch (variant) {
1101 |           case "se":
1102 |             ctx.moveTo(0,    0);    ctx.lineTo(W,    0);
1103 |             ctx.lineTo(W,    CELL); ctx.lineTo(CELL, CELL);
1104 |             ctx.lineTo(CELL, H);    ctx.lineTo(0,    H);
1105 |             break;
1106 |           case "sw":
1107 |             ctx.moveTo(W,      0);    ctx.lineTo(0,      0);
1108 |             ctx.lineTo(0,      CELL); ctx.lineTo(W-CELL, CELL);
1109 |             ctx.lineTo(W-CELL, H);    ctx.lineTo(W,      H);
1110 |             break;
1111 |           case "ne":
1112 |             ctx.moveTo(0,    H);      ctx.lineTo(W,    H);
1113 |             ctx.lineTo(W,    H-CELL); ctx.lineTo(CELL, H-CELL);
1114 |             ctx.lineTo(CELL, 0);      ctx.lineTo(0,    0);
1115 |             break;
1116 |           case "nw":
1117 |             ctx.moveTo(W,      H);      ctx.lineTo(0,      H);
1118 |             ctx.lineTo(0,      H-CELL); ctx.lineTo(W-CELL, H-CELL);
1119 |             ctx.lineTo(W-CELL, 0);      ctx.lineTo(W,      0);
1120 |             break;
1121 |         }
1122 |         ctx.closePath();
1123 |         ctx.fillStyle   = conflict ? "rgba(255,60,60,0.35)"  : fillColor;
1124 |         ctx.strokeStyle = conflict ? "rgba(255,80,80,0.9)"   : strokeColor;
1125 |         ctx.lineWidth = 2; ctx.fill(); ctx.stroke();
