btnRug.addEventListener("click", toggleRugMode);

// ── Donut mode ────────────────────────────────────────────────────────────
const DONUT_COLORS = [
  "#e8c84a","#5bbfe8","#e87a5b","#8bde6a",
  "#c45be8","#5be8b8","#e85b9a","#a0c860",
];

/** Return all {r,c} cells in the ring of the given outer bbox. */
function donutCells(rMin, cMin, rMax, cMax) {
  const ring = [];
  for (let r = rMin; r <= rMax; r++) {
    for (let c = cMin; c <= cMax; c++) {
      if (r === rMin || r === rMax || c === cMin || c === cMax) {
        ring.push({r, c});
      }
    }
  }
  return ring;
}

function hasConflictForDonut(rMin, cMin, rMax, cMax, ignoreId=null) {
  if (rMin<0||cMin<0||rMax>=SIZE||cMax>=SIZE) return true;
  for (const {r,c} of donutCells(rMin, cMin, rMax, cMax)) {
    for (const tid of tableGrid[r][c]) { if (tid !== ignoreId) return true; }
  }
  return false;
}

function stampDonut(t) {
  for (const {r,c} of donutCells(t.rMin, t.cMin, t.rMax, t.cMax)) {
    cells[r][c].classList.remove("selected","light","dark","preview");
    cells[r][c].style.backgroundColor = t.color;
    cells[r][c].style.opacity = "0.85";
    if (!tableGrid[r][c].includes(t.id)) tableGrid[r][c].push(t.id);
  }
}

function eraseDonut(t) {
  for (const {r,c} of donutCells(t.rMin, t.cMin, t.rMax, t.cMax)) {
    tableGrid[r][c] = tableGrid[r][c].filter(id => id !== t.id);
    if (tableGrid[r][c].length === 0) { resetCell(r,c); }
    else {
      const top = tables.find(p => p.id === tableGrid[r][c][tableGrid[r][c].length-1]);
      if (top) { cells[r][c].style.backgroundColor = top.color; cells[r][c].style.opacity="0.85"; }
    }
  }
}

/** Draw a hollow rectangle (ring) onto a canvas context. */
function drawDonut(ctx, W, H, rows, cols, fillColor, strokeColor, conflict) {
  ctx.clearRect(0, 0, W, H);
  const fc = conflict ? "rgba(255,60,60,0.45)" : fillColor;
  const sc = conflict ? "rgba(255,80,80,0.9)"  : strokeColor;
  // Outer rect
  ctx.fillStyle = fc;
  ctx.fillRect(0, 0, W, H);
  // Punch out the hole (inner rect, inset 1 cell on each side)
  ctx.clearRect(CELL, CELL, W - 2*CELL, H - 2*CELL);
  // Outer border
  ctx.strokeStyle = sc;
  ctx.lineWidth = 2;
  ctx.strokeRect(1, 1, W-2, H-2);
  // Inner border (hole edge)
  ctx.strokeRect(CELL+1, CELL+1, W - 2*CELL - 2, H - 2*CELL - 2);
}

function renderDonutEl(t) {
  const W = (t.cMax - t.cMin + 1) * CELL;
  const H = (t.rMax - t.rMin + 1) * CELL;
  t.el.style.left   = (t.cMin * CELL) + "px";
  t.el.style.top    = (t.rMin * CELL) + "px";
  t.el.style.width  = W + "px";
  t.el.style.height = H + "px";
  t.canvas.width = W; t.canvas.height = H;
  drawDonut(t.canvas.getContext("2d"), W, H,
            t.rMax - t.rMin + 1, t.cMax - t.cMin + 1,
            t.color + "99", t.color, false);
}

function toggleDonutMode() { if (donutMode) exitDonutMode(); else enterDonutMode(); }

function enterDonutMode() {
  exitCouchMode(); exitChairMode(); exitLsofaMode(); exitRugMode();
  donutMode = true;
  btnDonut.style.borderColor = "#e8c84a";
  btnDonut.style.background  = "#5a4a00";
  board.style.cursor = "none";
}

function exitDonutMode() {
  if (!donutMode) return;
  donutMode = false;
  ghostDonutOrientation = "h";
  btnDonut.style.borderColor = "";
  btnDonut.style.background  = "";
  board.style.cursor = "crosshair";
  donutGhostEl.style.display = "none";
}

/** Default ghost size for the current orientation. */
function donutGhostDims() {
  return ghostDonutOrientation === "h"
    ? { rows: DONUT_MIN_ROWS, cols: DONUT_MIN_COLS + 2 }  // wider landscape
    : { rows: DONUT_MIN_ROWS + 2, cols: DONUT_MIN_COLS };  // taller portrait
}

function updateDonutGhost(row, col) {
  const { rows, cols } = donutGhostDims();
  const rMin = Math.max(0, Math.min(row - Math.floor(rows/2), SIZE - rows));
  const cMin = Math.max(0, Math.min(col - Math.floor(cols/2), SIZE - cols));
  const rMax = rMin + rows - 1, cMax = cMin + cols - 1;
  const W = cols * CELL, H = rows * CELL;
  donutGhostEl.style.left   = (cMin * CELL) + "px";
  donutGhostEl.style.top    = (rMin * CELL) + "px";
  donutGhostEl.style.width  = W + "px";
  donutGhostEl.style.height = H + "px";
  donutGhostEl.style.display = "block";
  donutGhostCanvas.width = W; donutGhostCanvas.height = H;
  const conflict = hasConflictForDonut(rMin, cMin, rMax, cMax);
  drawDonut(donutGhostCanvas.getContext("2d"), W, H, rows, cols,
            "rgba(232,200,74,0.28)", "#e8c84a", conflict);
}

function placeDonut(row, col) {
  const { rows, cols } = donutGhostDims();
  const rMin = Math.max(0, Math.min(row - Math.floor(rows/2), SIZE - rows));
  const cMin = Math.max(0, Math.min(col - Math.floor(cols/2), SIZE - cols));
  const rMax = rMin + rows - 1, cMax = cMin + cols - 1;
  if (hasConflictForDonut(rMin, cMin, rMax, cMax)) return;

  const color = DONUT_COLORS[donutCount % DONUT_COLORS.length];
  const id    = tableCount++; donutCount++;
  const label = `Donut ${donutCount}`;

  const el     = document.createElement("div");
  el.className = "donut-rect";
  const canvas = document.createElement("canvas");
  canvas.style.display = "block";
  el.appendChild(canvas);

  const t = { id, type:"donut", rMin, cMin, rMax, cMax, color, label, el, canvas };
  tables.push(t);
  renderDonutEl(t);
  stampDonut(t);
  overlay.appendChild(el);

  el.addEventListener("mousedown", (e) => { if (donutMode) return; onTableMouseDown(e, t); });
  el.addEventListener("click",     (e) => { e.stopPropagation(); if (!donutMode) selectTable(t); });
}

/** Rotate a donut 90° CW (swap rows↔cols), enforce min/max, reject if conflict. */
function rotateDonut(t) {
  const h = t.rMax - t.rMin; // 0-based span
  const w = t.cMax - t.cMin;
  const newRows = w + 1, newCols = h + 1;
  if (newRows < DONUT_MIN_ROWS || newCols < DONUT_MIN_COLS) return;
  if (newRows > DONUT_MAX_ROWS || newCols > DONUT_MAX_COLS) return;
  const newRMax = Math.min(t.rMin + w, SIZE - 1);
  const newCMax = Math.min(t.cMin + h, SIZE - 1);
  if (hasConflictForDonut(t.rMin, t.cMin, newRMax, newCMax, t.id)) return;
  eraseDonut(t);
  t.rMax = newRMax; t.cMax = newCMax;
  stampDonut(t);
  renderDonutEl(t);
}

board.addEventListener("mousemove", (e) => {
  if (!donutMode) return;
  const cell = e.target.closest(".cell");
  if (!cell) return;
  updateDonutGhost(parseInt(cell.dataset.row), parseInt(cell.dataset.col));
});
board.addEventListener("mouseleave", () => { if (donutMode) donutGhostEl.style.display = "none"; });
board.addEventListener("click", (e) => {
  if (!donutMode) return;
  const cell = e.target.closest(".cell");
  if (!cell) return;
  placeDonut(parseInt(cell.dataset.row), parseInt(cell.dataset.col));
});

