function applySelPreview(curRow,curCol) {
  clearClass("preview");
  clearClass("conflict");
  clearClass("punch-preview");
  clearClass("punch-conflict");
  const r = selPreviewRect(curRow,curCol);
  const punchTarget = getPunchTarget(r);
  if (punchTarget) {
    // All cells in selection get punch-preview colour
    for (let row=r.rMin;row<=r.rMax;row++)
      for (let col=r.cMin;col<=r.cMax;col++)
        cells[row][col].classList.add("punch-preview");
  } else {
    for (let row=r.rMin;row<=r.rMax;row++) {
      for (let col=r.cMin;col<=r.cMax;col++) {
        if (tableGrid[row][col].length > 0) {
          cells[row][col].classList.add("conflict");
        } else {
          cells[row][col].classList.add("preview");
        }
      }
    }
  }
  selOverlay.style.left    = (r.cMin * CELL) + "px";
  selOverlay.style.top     = (r.rMin * CELL) + "px";
  selOverlay.style.width   = ((r.cMax - r.cMin + 1) * CELL) + "px";
  selOverlay.style.height  = ((r.rMax - r.rMin + 1) * CELL) + "px";
  selOverlay.style.display = "block";
}

/**
 * If `sel` is a valid punch rect (completely inside exactly one plain table
 * with ≥1 cell margin on all sides), return that table. Otherwise null.
 */
function getPunchTarget(sel) {
  // Must leave at least 1-cell border → outer must be at least 3×3
  const outerRMin = sel.rMin - 1, outerCMin = sel.cMin - 1;
  const outerRMax = sel.rMax + 1, outerCMax = sel.cMax + 1;
  if (outerRMin < 0 || outerCMin < 0 || outerRMax >= SIZE || outerCMax >= SIZE) return null;
  // Every cell in the selection must belong to the same single table (type:"table")
  let target = null;
  for (let r=sel.rMin; r<=sel.rMax; r++) {
    for (let c=sel.cMin; c<=sel.cMax; c++) {
      const ids = tableGrid[r][c].filter(id => {
        const p = tables.find(t => t.id === id);
        return p && p.type === "table";
      });
      if (ids.length !== 1) return null;
      const piece = tables.find(t => t.id === ids[0]);
      if (!target) target = piece;
      else if (target !== piece) return null;
    }
  }
  if (!target) return null;
  // The outer ring cells must all also belong to the same target
  // (ensures the hole is truly interior, not on the edge of the table)
  if (target.rMin > outerRMin || target.cMin > outerCMin ||
      target.rMax < outerRMax || target.cMax < outerCMax) return null;
  return target;
}

