/** Return all {r,c} cells in the ring (outer rect minus hole rect). */
function donutCells(t) {
  const ring = [];
  for (let r = t.rMin; r <= t.rMax; r++) {
    for (let c = t.cMin; c <= t.cMax; c++) {
      const h = t.hole;
      if (r >= h.rMin && r <= h.rMax && c >= h.cMin && c <= h.cMax) continue;
      ring.push({r, c});
    }
  }
  return ring;
}

function hasConflictForDonut(t, ignoreId=null) {
  if (t.rMin<0||t.cMin<0||t.rMax>=SIZE||t.cMax>=SIZE) return true;
  for (const {r,c} of donutCells(t))
    for (const tid of tableGrid[r][c]) { if (tid !== ignoreId) return true; }
  return false;
}

function stampDonut(t) {
  for (const {r,c} of donutCells(t)) {
    cells[r][c].classList.remove("selected","light","dark","preview","punch-preview");
    cells[r][c].style.backgroundColor = t.color;
    cells[r][c].style.opacity = "0.85";
    if (!tableGrid[r][c].includes(t.id)) tableGrid[r][c].push(t.id);
  }
}

function eraseDonut(t) {
  for (const {r,c} of donutCells(t)) {
    tableGrid[r][c] = tableGrid[r][c].filter(id => id !== t.id);
    if (tableGrid[r][c].length === 0) { resetCell(r,c); }
    else {
      const top = tables.find(p => p.id === tableGrid[r][c][tableGrid[r][c].length-1]);
      if (top) { cells[r][c].style.backgroundColor = top.color; cells[r][c].style.opacity="0.85"; }
    }
  }
  // Clear the hole cells (they were removed from the outer table's stamp when we punched)
  const h = t.hole;
  for (let r=h.rMin; r<=h.rMax; r++) {
    for (let c=h.cMin; c<=h.cMax; c++) {
      tableGrid[r][c] = tableGrid[r][c].filter(id => id !== t.id);
      if (tableGrid[r][c].length === 0) resetCell(r,c);
    }
  }
}

/** Draw a hollow rectangle (ring) onto a canvas context. */
function drawDonut(ctx, W, H, holeX, holeY, holeW, holeH, fillColor, strokeColor, conflict) {
  ctx.clearRect(0, 0, W, H);
  const fc = conflict ? "rgba(255,60,60,0.45)" : fillColor;
  const sc = conflict ? "rgba(255,80,80,0.9)"  : strokeColor;
  ctx.fillStyle = fc;
  ctx.fillRect(0, 0, W, H);
  ctx.clearRect(holeX, holeY, holeW, holeH);
  ctx.strokeStyle = sc; ctx.lineWidth = 2;
  ctx.strokeRect(1, 1, W-2, H-2);
  ctx.strokeRect(holeX+1, holeY+1, holeW-2, holeH-2);
}

function renderDonutEl(t) {
  const W = (t.cMax - t.cMin + 1) * CELL, H = (t.rMax - t.rMin + 1) * CELL;
  const holeX = (t.hole.cMin - t.cMin) * CELL;
  const holeY = (t.hole.rMin - t.rMin) * CELL;
  const holeW = (t.hole.cMax - t.hole.cMin + 1) * CELL;
  const holeH = (t.hole.rMax - t.hole.rMin + 1) * CELL;
  t.el.style.left=t.cMin*CELL+"px"; t.el.style.top=t.rMin*CELL+"px";
  t.el.style.width=W+"px"; t.el.style.height=H+"px";
  t.canvas.width=W; t.canvas.height=H;
  drawDonut(t.canvas.getContext("2d"), W, H, holeX, holeY, holeW, holeH,
            t.color+"99", t.color, false);
}

/**
 * Convert the current selection into a hole punched through the containing table.
 * Press [U] after drag-selecting an interior region of a placed table.
 */
function punchDonut() {
  if (!selection) return;
  const target = getPunchTarget(selection);
  if (!target) return; // flash red on sel overlay as feedback
  if (target.type !== "table") return;

  const hole = { rMin: selection.rMin, cMin: selection.cMin,
                 rMax: selection.rMax, cMax: selection.cMax };

  // 1. Remove the hole cells from the tableGrid (clear old table stamp there)
  for (let r=hole.rMin; r<=hole.rMax; r++) {
    for (let c=hole.cMin; c<=hole.cMax; c++) {
      tableGrid[r][c] = tableGrid[r][c].filter(id => id !== target.id);
      if (tableGrid[r][c].length === 0) resetCell(r,c);
    }
  }

  // 2. Convert the table element to a donut canvas element
  const newEl     = document.createElement("div");
  newEl.className = "donut-rect";
  const canvas    = document.createElement("canvas");
  canvas.style.display = "block";
  newEl.appendChild(canvas);

  if (target.el.parentNode) target.el.parentNode.removeChild(target.el);
  target.el = newEl;
  target.canvas = canvas;
  target.type = "donut";
  target.hole = hole;
  donutCount++;
  if (!target.label.startsWith("Donut")) target.label = "Donut " + donutCount;

  renderDonutEl(target);
  overlay.appendChild(newEl);

  newEl.addEventListener("mousedown", (e) => onTableMouseDown(e, target));
  newEl.addEventListener("click", (e) => { e.stopPropagation(); selectTable(target); });

  // 3. Clear selection
  selection = null;
  clearClass("preview"); clearClass("conflict");
  clearClass("punch-preview"); clearClass("punch-conflict");
  renderSelection();
}

function rotateDonut(t) {
  const outerH = t.rMax - t.rMin, outerW = t.cMax - t.cMin;
  const newRMax = Math.min(t.rMin + outerW, SIZE - 1);
  const newCMax = Math.min(t.cMin + outerH, SIZE - 1);
  // Rotate hole 90° CW around outer top-left
  const hR = t.hole.rMin - t.rMin, hC = t.hole.cMin - t.cMin;
  const hH = t.hole.rMax - t.hole.rMin, hW = t.hole.cMax - t.hole.cMin;
  const newHoleRMin = t.rMin + hC, newHoleCMin = t.cMin + (outerH - hR - hH);
  const newHole = { rMin: newHoleRMin, cMin: newHoleCMin,
                    rMax: newHoleRMin + hW, cMax: newHoleCMin + hH };
  if (newRMax >= SIZE || newCMax >= SIZE) return;
  // Check ring cells of the rotated shape for conflicts (ignoring self)
  const rotated = { ...t, rMax: newRMax, cMax: newCMax, hole: newHole };
  if (hasConflictForDonut(rotated, t.id)) return;
  eraseDonut(t);
  t.rMax = newRMax; t.cMax = newCMax; t.hole = newHole;
  stampDonut(t);
  renderDonutEl(t);
}

