  t.el.style.width=W+"px"; t.el.style.height=H+"px";
  t.canvas.width=W; t.canvas.height=H;
  drawDonut(t.canvas.getContext("2d"), W, H, t.color+"99", t.color, false);
}

function toggleDonutMode() { if (donutMode) exitDonutMode(); else enterDonutMode(); }

function enterDonutMode() {
  exitCouchMode(); exitChairMode(); exitLsofaMode(); exitRugMode();
  donutMode = true;
  btnDonut.style.borderColor = "#e8c84a";
  btnDonut.style.background  = "#5a4a00";
  board.style.cursor = "none";
}

function exitDonutMode() {
  if (!donutMode) return;
  donutMode = false;
  ghostDonutOrientation = "h";
  btnDonut.style.borderColor = "";
  btnDonut.style.background  = "";
  board.style.cursor = "crosshair";
  donutGhostEl.style.display = "none";
}

function donutGhostDims() {
  return ghostDonutOrientation === "h"
    ? { rows: DONUT_MIN_ROWS, cols: DONUT_MIN_COLS + 2 }
    : { rows: DONUT_MIN_ROWS + 2, cols: DONUT_MIN_COLS };
}

function updateDonutGhost(row, col) {
  const { rows, cols } = donutGhostDims();
  const rMin = Math.max(0, Math.min(row - Math.floor(rows/2), SIZE - rows));
  const cMin = Math.max(0, Math.min(col - Math.floor(cols/2), SIZE - cols));
  const rMax = rMin + rows - 1, cMax = cMin + cols - 1;
  const W = cols * CELL, H = rows * CELL;
  donutGhostEl.style.left=(cMin*CELL)+"px"; donutGhostEl.style.top=(rMin*CELL)+"px";
  donutGhostEl.style.width=W+"px"; donutGhostEl.style.height=H+"px";
  donutGhostEl.style.display = "block";
  donutGhostCanvas.width=W; donutGhostCanvas.height=H;
  const conflict = hasConflictForDonut(rMin, cMin, rMax, cMax);
  drawDonut(donutGhostCanvas.getContext("2d"), W, H,
            "rgba(232,200,74,0.28)", "#e8c84a", conflict);
}

function placeDonut(row, col) {
  const { rows, cols } = donutGhostDims();
  const rMin = Math.max(0, Math.min(row - Math.floor(rows/2), SIZE - rows));
  const cMin = Math.max(0, Math.min(col - Math.floor(cols/2), SIZE - cols));
  const rMax = rMin + rows - 1, cMax = cMin + cols - 1;
  if (hasConflictForDonut(rMin, cMin, rMax, cMax)) return;

  const color = DONUT_COLORS[donutCount % DONUT_COLORS.length];
  const id    = tableCount++; donutCount++;

  const el     = document.createElement("div");
  el.className = "donut-rect";
  const canvas = document.createElement("canvas");
  canvas.style.display = "block";
  el.appendChild(canvas);

  const t = { id, type:"donut", rMin, cMin, rMax, cMax, color,
              label:`Donut ${donutCount}`, el, canvas };
  tables.push(t);
  renderDonutEl(t);
  stampDonut(t);
  overlay.appendChild(el);

  el.addEventListener("mousedown", (e) => { if (donutMode) return; onTableMouseDown(e, t); });
  el.addEventListener("click",     (e) => { e.stopPropagation(); if (!donutMode) selectTable(t); });
}

function rotateDonut(t) {
  const h = t.rMax - t.rMin, w = t.cMax - t.cMin;
  const newRows = w + 1, newCols = h + 1;
  if (newRows < DONUT_MIN_ROWS || newCols < DONUT_MIN_COLS) return;
  if (newRows > DONUT_MAX_ROWS || newCols > DONUT_MAX_COLS) return;
  const newRMax = Math.min(t.rMin + w, SIZE - 1);
  const newCMax = Math.min(t.cMin + h, SIZE - 1);
  if (hasConflictForDonut(t.rMin, t.cMin, newRMax, newCMax, t.id)) return;
  eraseDonut(t);
  t.rMax = newRMax; t.cMax = newCMax;
  stampDonut(t);
  renderDonutEl(t);
}

board.addEventListener("mousemove", (e) => {
  if (!donutMode) return;
  const cell = e.target.closest(".cell");
  if (!cell) return;
  updateDonutGhost(parseInt(cell.dataset.row), parseInt(cell.dataset.col));
});
board.addEventListener("mouseleave", () => { if (donutMode) donutGhostEl.style.display = "none"; });
board.addEventListener("click", (e) => {
  if (!donutMode) return;
  const cell = e.target.closest(".cell");
  if (!cell) return;
  placeDonut(parseInt(cell.dataset.row), parseInt(cell.dataset.col));
});

