/**
 * Convert the current selection into a hole punched through the containing table.
 * Press [U] after drag-selecting an interior region of a placed table.
 */
function punchDonut() {
  if (!selection) return;
  const target = getPunchTarget(selection);
  if (!target || target.type !== "table") return;

  const hole = { rMin: selection.rMin, cMin: selection.cMin,
                 rMax: selection.rMax, cMax: selection.cMax };

  // Remove the hole cells from the tableGrid
  for (let r=hole.rMin; r<=hole.rMax; r++) {
    for (let c=hole.cMin; c<=hole.cMax; c++) {
      tableGrid[r][c] = tableGrid[r][c].filter(id => id !== target.id);
      if (tableGrid[r][c].length === 0) resetCell(r,c);
    }
  }

  // Replace the table's div with a donut canvas element
  const newEl     = document.createElement("div");
  newEl.className = "donut-rect";
  const canvas    = document.createElement("canvas");
  canvas.style.display = "block";
  newEl.appendChild(canvas);

  if (target.el.parentNode) target.el.parentNode.removeChild(target.el);
  target.el = newEl;
  target.canvas = canvas;
  target.type = "donut";
  target.hole = hole;
  donutCount++;
  if (!target.label.startsWith("Donut")) target.label = "Donut " + donutCount;

  renderDonutEl(target);
  overlay.appendChild(newEl);

  newEl.addEventListener("mousedown", (e) => onTableMouseDown(e, target));
  newEl.addEventListener("click", (e) => { e.stopPropagation(); selectTable(target); });

  selection = null;
  clearClass("preview"); clearClass("conflict");
  clearClass("punch-preview"); clearClass("punch-conflict");
  renderSelection();
}

function rotateDonut(t) {
  const outerH = t.rMax - t.rMin, outerW = t.cMax - t.cMin;
  const newRMax = Math.min(t.rMin + outerW, SIZE - 1);
  const newCMax = Math.min(t.cMin + outerH, SIZE - 1);
  const hR = t.hole.rMin - t.rMin, hC = t.hole.cMin - t.cMin;
  const hH = t.hole.rMax - t.hole.rMin, hW = t.hole.cMax - t.hole.cMin;
  // 90° CW rotation of the hole offset
  const newHoleRMin = t.rMin + hC, newHoleCMin = t.cMin + (outerH - hR - hH);
  const newHole = { rMin: newHoleRMin, cMin: newHoleCMin,
                    rMax: newHoleRMin + hW, cMax: newHoleCMin + hH };
  if (newRMax >= SIZE || newCMax >= SIZE) return;
  const rotated = { ...t, rMax: newRMax, cMax: newCMax, hole: newHole };
  if (hasConflictForDonut(rotated, t.id)) return;
  eraseDonut(t);
  t.rMax = newRMax; t.cMax = newCMax; t.hole = newHole;
  stampDonut(t);
  renderDonutEl(t);
}

