      // If there are chairs left here, refresh their badge
      const hasChair = tableGrid[r][c].some(id => {
        const p = tables.find(q => q.id === id);
        return p && p.type === "chair";
      });
      if (hasChair || t.type === "chair") refreshChairBadge(r, c);
    }
  }
}

