/**
 * Fracture any type:"table" pieces whose footprint overlaps the given rect.
 * The overlapping table is deleted and replaced by up to 4 non-overlapping
 * rectangular shards (top / bottom / left strip / right strip) using a
 * guillotine cut around the intersection.
 * Call this AFTER the new piece has been stamped so tableGrid is current.
 * Pass the new piece's id as `ignoreId` so we don't fracture the piece itself.
 */
function fractureTablesUnder(nR1, nC1, nR2, nC2, ignoreId) {
  // Collect every table-type piece whose cells overlap the new rect
  const victims = new Set();
  for (let r = nR1; r <= nR2; r++) {
    for (let c = nC1; c <= nC2; c++) {
      for (const tid of tableGrid[r][c]) {
        if (tid === ignoreId) continue;
        const p = tables.find(t => t.id === tid);
        if (p && p.type === "table") victims.add(p);
      }
    }
  }
  for (const victim of victims) {
    // Intersection of victim with the new rect
    const oR1 = Math.max(victim.rMin, nR1), oC1 = Math.max(victim.cMin, nC1);
    const oR2 = Math.min(victim.rMax, nR2), oC2 = Math.min(victim.cMax, nC2);
    if (oR1 > oR2 || oC1 > oC2) continue; // no actual overlap (shouldn't happen)

    // Remember bounds before deletion
    const vR1 = victim.rMin, vC1 = victim.cMin;
    const vR2 = victim.rMax, vC2 = victim.cMax;
    const vColor = victim.color;

    deleteTable(victim);

    // Up to 4 shards — each only created if non-empty
    const shards = [
      { rMin: vR1,    cMin: vC1,    rMax: oR1-1, cMax: vC2    }, // top
      { rMin: oR2+1,  cMin: vC1,    rMax: vR2,   cMax: vC2    }, // bottom
      { rMin: oR1,    cMin: vC1,    rMax: oR2,   cMax: oC1-1  }, // left
      { rMin: oR1,    cMin: oC2+1,  rMax: oR2,   cMax: vC2    }, // right
    ];
    for (const s of shards) {
      if (s.rMin > s.rMax || s.cMin > s.cMax) continue; // empty shard
      spawnTable(s.rMin, s.cMin, s.rMax, s.cMax, vColor);
    }
  }
}

/** Create and register a plain table object (used both by placeTable and fracture). */
function spawnTable(rMin, cMin, rMax, cMax, color) {
  const id    = tableCount++;
  const label = `Table ${id + 1}`;
  const el    = document.createElement("div");
  el.className = "table-rect";
  el.style.backgroundColor = color + "44";
  el.style.borderColor     = color;
  el.textContent = label;
  const t = { id, rMin, cMin, rMax, cMax, color, label, el };
  tables.push(t);
  positionEl(t);
  stampTable(t);
  overlay.appendChild(el);
  el.addEventListener("mousedown", (e) => onTableMouseDown(e, t));
  el.addEventListener("click",     (e) => { e.stopPropagation(); selectTable(t); });
  return t;
}

